import sys

def is_sorted(arr):
    """Check if array is non-decreasing."""
    return all(arr[i] <= arr[i + 1] for i in range(len(arr) - 1))

def thanos_sort(arr):
    n = len(arr)
    # Base case: if array is sorted, return its length
    if is_sorted(arr):
        return n
    # Otherwise, split into halves and recurse
    mid = n // 2
    left = arr[:mid]
    right = arr[mid:]
    # Return the best result from either half
    return max(thanos_sort(left), thanos_sort(right))

def main():
    data = sys.stdin.read().strip().split()
    n = int(data[0])
    arr = list(map(int, data[1:]))
    print(thanos_sort(arr))

if __name__ == "__main__":
    main()

