MOD = 998244353

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    K = int(next(it))
    a = [[int(next(it)) for _ in range(N)] for _ in range(N)]

    # We need to count the number of permutations of rows and columns independently
    # that can be achieved via allowed swaps.
    # This corresponds to counting connected components in two graphs:
    # row graph: vertices = rows, edge between x and y if for all j, a[x][j] + a[y][j] <= K
    # column graph: vertices = columns, edge between x and y if for all i, a[i][x] + a[i][y] <= K

    # Build row graph
    row_adj = [[False]*N for _ in range(N)]
    for r1 in range(N):
        for r2 in range(r1+1, N):
            ok = True
            for j in range(N):
                if a[r1][j] + a[r2][j] > K:
                    ok = False
                    break
            if ok:
                row_adj[r1][r2] = row_adj[r2][r1] = True

    # Build column graph
    col_adj = [[False]*N for _ in range(N)]
    for c1 in range(N):
        for c2 in range(c1+1, N):
            ok = True
            for i in range(N):
                if a[i][c1] + a[i][c2] > K:
                    ok = False
                    break
            if ok:
                col_adj[c1][c2] = col_adj[c2][c1] = True

    # DFS to get component sizes in row graph
    row_visited = [False]*N
    row_sizes = []
    for i in range(N):
        if not row_visited[i]:
            stack = [i]
            cnt = 0
            while stack:
                u = stack.pop()
                if row_visited[u]:
                    continue
                row_visited[u] = True
                cnt += 1
                for v in range(N):
                    if row_adj[u][v] and not row_visited[v]:
                        stack.append(v)
            if cnt > 0:
                row_sizes.append(cnt)

    # DFS to get component sizes in column graph
    col_visited = [False]*N
    col_sizes = []
    for i in range(N):
        if not col_visited[i]:
            stack = [i]
            cnt = 0
            while stack:
                u = stack.pop()
                if col_visited[u]:
                    continue
                col_visited[u] = True
                cnt += 1
                for v in range(N):
                    if col_adj[u][v] and not col_visited[v]:
                        stack.append(v)
            if cnt > 0:
                col_sizes.append(cnt)

    # Precompute factorials
    fact = [1]*(N+1)
    for i in range(1, N+1):
        fact[i] = fact[i-1]*i % MOD

    # Number of ways for rows = product of factorials of component sizes
    # because within each connected component we can permute arbitrarily
    row_ways = 1
    for sz in row_sizes:
        row_ways = (row_ways * fact[sz]) % MOD

    # Number of ways for columns
    col_ways = 1
    for sz in col_sizes:
        col_ways = (col_ways * fact[sz]) % MOD

    ans = (row_ways * col_ways) % MOD
    print(ans)

if __name__ == "__main__":
