def solve():
    n, H = map(int, input().split())

    def max_sand(k):
        if k <= H:
            # shape: 1,2,...,k
            if k * (k + 1) // 2 >= n:  # avoid overflow check
                return True
            return k * (k + 1) // 2 >= n
        else:
            # k > H
            # m in [ceil((k+1)/2), min(k, (H+k)//2)]
            m_low = (k + 1) // 2
            m_high = min(k, (H + k) // 2)
            if m_low > m_high:
                return False
            # sand = (4mk - 2m^2 + 2m - k^2 - k) / 2
            # We want max over m in [m_low, m_high]
            # Derivative: -4m + 4k + 2 = 0 -> m = k + 0.5
            # So max at m = m_high or m = m_low
            def sand(m):
                return (4 * m * k - 2 * m * m + 2 * m - k * k - k) // 2
            max_s = max(sand(m_low), sand(m_high))
            # check m_high - 1
            if m_high - 1 >= m_low:
                max_s = max(max_s, sand(m_high - 1))
            return max_s >= n

    low, high = 1, 2 * int(1e9) + 10
    while low < high:
        mid = (low + high) // 2
        if max_sand(mid):
            high = mid
        else:
            low = mid + 1
    print(low)

if __name__ == "__main__":
    solve()

