    row_visited = [False] * N
    row_components = []

    for start in range(N):
        if not row_visited[start]:
            stack = [start]
            comp = []
            while stack:
                v = stack.pop()
                if row_visited[v]:
                    continue
                row_visited[v] = True
                comp.append(v)
                for u in range(N):
                    if row_adj[v][u] and not row_visited[u]:
