    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD

    ans = 1
    for comp in col_components:
        ans = ans * fact[len(comp)] % MOD
    for comp in row_components:
        ans = ans * fact[len(comp)] % MOD

