def solve() -> None:
    s = sys.stdin.readline().strip()
    n = len(s)
    if n % 2 != 0:
        print(-1)
        return

    # Count movements
    left = right = up = down = 0
    for ch in s:
        if ch == 'L':
            left += 1
        elif ch == 'R':
            right += 1
        elif ch == 'U':
            up += 1
        elif ch == 'D':
            down += 1

    # Net horizontal and vertical displacements
    horiz_diff = abs(left - right)
    vert_diff = abs(up - down)

    # Total changes needed: 
    # For each axis, we can fix the imbalance by changing half of the difference,
    # because changing one character affects one axis at a time.
    # After fixing imbalance, any remaining edits must be even and are counted as 2 per swap.
    if (horiz_diff + vert_diff) % 2 != 0:
        print(-1)
    else:
        print((horiz_diff + vert_diff) // 2)

