def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])
    a = list(map(int, data[2:2 + m]))

    # Original total
    original_total = 0
    for i in range(m - 1):
        original_total += abs(a[i] - a[i + 1])

    # Build adjacency lists: for each page number, store neighbor values
    adj = [[] for _ in range(n + 1)]
    for i in range(m):
        if i > 0 and a[i - 1] != a[i]:
            adj[a[i]].append(a[i - 1])
        if i < m - 1 and a[i + 1] != a[i]:
            adj[a[i]].append(a[i + 1])

    best_saving = 0
    for x in range(1, n + 1):
        if not adj[x]:
            continue
        # Sort neighbors to find median efficiently
        neighbors = sorted(adj[x])
        median = neighbors[len(neighbors) // 2]
        # Compute saving if we change all x to median
        saving = 0
        for v in adj[x]:
            saving += abs(v - x) - abs(v - median)
        if saving > best_saving:
            best_saving = saving

    print(original_total - best_saving)

if __name__ == "__main__":
    solve()

