import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, m = map(int, data[:2])
    edges = []
    pos = 2
    for _ in range(m):
        a = int(data[pos]) - 1
        b = int(data[pos + 1]) - 1
        edges.append((a, b))
        pos += 2

    # adjacency lists: forward and backward
    out_adj = [[] for _ in range(n)]
    in_adj = [[] for _ in range(n)]
    for a, b in edges:
        out_adj[a].append(b)
        in_adj[b].append(a)

    # cnt[x][y] = number of paths of length 2 from x to y
    cnt = [[0] * n for _ in range(n)]

    # Count paths of length 2: for each middle node u, go over pairs (v, w) in its adjacency
    for u in range(n):
        # For all nodes v that have edge v->u
        for v in in_adj[u]:
            # For all nodes w that have edge u->w (except v to avoid loops? but v could be w only if self-loop, not allowed)
            for w in out_adj[u]:
                if v != w:
                    cnt[v][w] += 1

    ans = 0
    for i in range(n):
        for j in range(n):
            if i != j:
                c = cnt[i][j]
                if c >= 2:
                    # choose 2 different middle vertices from the c possibilities
                    ans += c * (c - 1) // 2
    print(ans)

