def solve():
    s = sys.stdin.read()
    n = len(s)
    i = 0
    lexemes = []

    while i < n:
        # Skip spaces
        while i < n and s[i] == ' ':
            i += 1
        if i >= n:
            break

        # If starts with quote
        if s[i] == '"':
            i += 1
            start = i
            while i < n and s[i] != '"':
