import sys

MOD = 10**9 + 7

def matmul(A, B, x):
    """Multiply two matrices modulo MOD, each matrix is x by x"""
    C = [[0] * x for _ in range(x)]
    for i in range(x):
        for k in range(x):
            if A[i][k] == 0:
                continue
            for j in range(x):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
    return C

def matpow(M, power, x):
    """Fast exponentiation of matrix M to the power 'power'"""
    result = [[0] * x for _ in range(x)]
    for i in range(x):
        result[i][i] = 1

    while power > 0:
        if power & 1:
            result = matmul(result, M, x)
        M = matmul(M, M, x)
        power >>= 1
    return result

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, b, k, x = map(int, data[:4])
    digits = list(map(int, data[4:4 + n]))

    # freq[0..9], but we only care about digits 1..9
    freq = [0] * 10
    for d in digits:
        freq[d] += 1

    # Transition matrix: ways to go from remainder i to remainder j
    trans = [[0] * x for _ in range(x)]
    for rem in range(x):
        for d in range(1, 10):
            if freq[d] == 0:
                continue
            new_rem = (rem * 10 + d) % x
            trans[rem][new_rem] = (trans[rem][new_rem] + freq[d]) % MOD

    # Matrix exponentiation: we need trans^(b)
    final_mat = matpow(trans, b, x)

    # Starting remainder is 0 (empty number)
    # We want ways to reach remainder k after b blocks
    ans = final_mat[0][k]
    print(ans)

