    # We'll use Kosaraju for clarity.
    # Build reversed graph
    radj = [[] for _ in range(N)]
    for u in range(N):
        for v in adj[u]:
            radj[v].append(u)

    # DFS on original graph
    order = []
    visited = [False] * N
    def dfs1(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

