    # For '=' we add both directions
    for i in range(n):
        row = table[i]
        for j, ch in enumerate(row):
            if ch == '=':
                adj[i].append(n + j)
                adj[n + j].append(i)
            elif ch == '<':
                adj[i].append(n + j)
            else:  # '>'
                adj[n + j].append(i)

    # First, find strongly connected components (Kosaraju or Tarjan)
    # We'll use Kosaraju for clarity.
    # Build reversed graph
    radj = [[] for _ in range(N)]
    for u in range(N):
        for v in adj[u]:
            radj[v].append(u)

    # DFS on original graph
    order = []
    visited = [False] * N
    def dfs1(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

    for i in range(N):
        if not visited[i]:
            dfs1(i)

    # DFS on reversed graph in reverse postorder
    comp = [-1] * N
    cur_comp = 0
    def dfs2(u, cur_comp):
        comp[u] = cur_comp
        for v in radj[u]:
            if comp[v] == -1:
                dfs2(v, cur_comp)

    for u in reversed(order):
        if comp[u] == -1:
            dfs2(u, cur_comp)
            cur_comp += 1
    comp_cnt = cur_comp

    # Check consistency: if there is an '=' between nodes in different SCC, impossible
    for i in range(n):
        row = table[i]
        for j, ch in enumerate(row):
            if ch == '=' and comp[i] != comp[n + j]:
                print("No")
                return

    # Build DAG of components
    dag_adj = [[] for _ in range(comp_cnt)]
    indeg = [0] * comp_cnt
    for u in range(N):
        cu = comp[u]
        for v in adj[u]:
            cv = comp[v]
            if cu != cv:
                dag_adj[cu].append(cv)

    # Remove duplicates
    for u in range(comp_cnt):
        dag_adj[u] = list(set(dag_adj[u]))
        for v in dag_adj[u]:
            indeg[v] += 1

    # Topological sort with longest path (since we want minimal max value)
    # Actually, we want minimal numbers such that edges are satisfied.
    # This is classic: assign 1 to sources, then propagate: val[v] = max(val[v], val[u] + 1) for u->v
    from collections import deque
    q = deque()
    val = [1] * comp_cnt
    for c in range(comp_cnt):
        if indeg[c] == 0:
            q.append(c)
    while q:
        u = q.popleft()
        for v in dag_adj[u]:
            val[v] = max(val[v], val[u] + 1)
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)

    # If indeg not all zero, there's a cycle -> contradiction
    if any(indeg):
        print("No")
        return

    # Check original constraints again using the computed values
    for i in range(n):
        row = table[i]
        for j, ch in enumerate(row):
            vi = val[comp[i]]
            vj = val[comp[n + j]]
            if ch == '<' and not (vi < vj):
                print("No")
                return
            if ch == '>' and not (vi > vj):
                print("No")
                return
            if ch == '=' and not (vi == vj):
                print("No")
                return

    # Output
    print("Yes")
    first_vals = [val[comp[i]] for i in range(n)]
    second_vals = [val[comp[n + j]] for j in range(m)]
    print(' '.join(map(str, first_vals)))
    print(' '.join(map(str, second_vals)))

if __name__ == "__main__":
    solve()

