import sys

MOD = 998244353

def solve():
    n, k = map(int, sys.stdin.readline().split())

    if k == 1:
        print(n % MOD)
        return

    if k > n:
        print(0)
        return

    # Sieve to get Omega(m)
    Omega = [0] * (n + 1)
    for i in range(2, n + 1):
        if Omega[i] == 0:  # i is prime
            for j in range(i, n + 1, i):
                # Add 1 for each prime factor i in j
                # But we need total with multiplicity: easier to store smallest prime factor and compute Omega
                # Let's do straightforward: while dividing
                # But here we can just add 1 for each occurrence in the sieve
                # Actually do Omega[j] += 1 for each j multiple of i
                # But that adds only once per prime factor, not multiplicity. So wrong.
                # Better: compute Omega by sieving with smallest prime factor method.
                pass

    # Let's compute Omega correctly:
    Omega = [0] * (n + 1)
    spf = list(range(n + 1))  # smallest prime factor
    for i in range(2, n + 1):
        if spf[i] == i:
            for j in range(i * i, n + 1, i):
                if spf[j] == j:
                    spf[j] = i

    Omega[1] = 0
    for i in range(2, n + 1):
        Omega[i] = Omega[i // spf[i]] + 1

    maxOmega = max(Omega)

    # Precompute factorials and inverse factorials up to maxOmega
    fact = [1] * (maxOmega + 2)
    inv_fact = [1] * (maxOmega + 2)
    for i in range(2, maxOmega + 2):
        fact[i] = fact[i-1] * i % MOD

    def mod_pow(a, b):
        res = 1
        while b:
            if b & 1:
                res = res * a % MOD
            a = a * a % MOD
            b >>= 1
        return res

    inv_fact[maxOmega+1] = mod_pow(fact[maxOmega+1], MOD-2)
    for i in range(maxOmega, -1, -1):
        inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

    def comb(a, b):
        if b < 0 or b > a:
            return 0
        return fact[a] * inv_fact[b] % MOD * inv_fact[a-b] % MOD

    # w[m] = comb(Omega[m], k-1) if Omega[m] >= k-1 else 0
    w = [0] * (n + 1)
    for m in range(1, n + 1):
        if Omega[m] >= k - 1:
            w[m] = comb(Omega[m], k - 1)

    # prefix sums of w
    prefix = [0] * (n + 1)
    for i in range(1, n + 1):
        prefix[i] = (prefix[i-1] + w[i]) % MOD

    ans = 0
    for m in range(1, n + 1):
        ans = (ans + prefix[n // m]) % MOD

    print(ans % MOD)

if __name__ == "__main__":
    solve()

