MOD = 998244353

def mod_pow(a, b, mod):
    res = 1
    while b:
        if b & 1:
            res = res * a % mod
        a = a * a % mod
        b >>= 1
    return res

def prepare_fac(n, mod):
    fac = [1] * (n + 1)
    inv_fac = [1] * (n + 1)
    for i in range(2, n + 1):
        fac[i] = fac[i-1] * i % mod
    inv_fac[n] = mod_pow(fac[n], mod-2, mod)
    for i in range(n-1, -1, -1):
        inv_fac[i] = inv_fac[i+1] * (i+1) % mod
    return fac, inv_fac

def comb(n, k, fac, inv_fac, mod):
    if k < 0 or k > n:
        return 0
    return fac[n] * inv_fac[k] % mod * inv_fac[n-k] % mod

def solve():
    import sys
    input = sys.stdin.read
    n, m = map(int, input().split())

    if n == 2:
        print(0)
        return

    fac, inv_fac = prepare_fac(m, MOD)

    ways_choose = comb(m, n-1, fac, inv_fac, MOD)
    ways_arrange = (n-2) * mod_pow(2, n-3, MOD) % MOD

    ans = ways_choose * ways_arrange % MOD
    print(ans)

if __name__ == "__main__":
    solve()

