import sys

def sieve(limit):
    spf = list(range(limit + 1))
    for i in range(2, int(limit**0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, limit + 1, i):
                if spf[j] == j:
                    spf[j] = i
    return spf

def factorize(x, spf):
    factors = {}
    while x > 1:
        p = spf[x]
        cnt = 0
        while x % p == 0:
            x //= p
            cnt += 1
        factors[p] = cnt
    return factors

def main():
    input_data = sys.stdin.read().strip().split()
    idx = 0
    n = int(input_data[idx]); idx += 1
    a = list(map(int, input_data[idx:idx + n])); idx += n
    b = list(map(int, input_data[idx:idx + n])); idx += n
    m = int(input_data[idx]); idx += 1

    points = []
    for i in range(n):
        points.append((a[i], 0, i + 1))
    for i in range(n):
        points.append((b[i], 1, i + 1))

    points.sort(key=lambda x: (x[0], x[1], x[2]))

    # spf up to 2n
    spf = sieve(2 * n + 5)

    # Exponent array for final multiplication
    prime_exp = {}

    # Process groups
    i = 0
    while i < 2 * n:
        j = i
        while j < 2 * n and points[j][0] == points[i][0]:
            j += 1
        t = j - i
        ca = sum(1 for k in range(i, j) if points[k][1] == 0)
        cb = t - ca

        # Add exponents for t!
        for num in range(1, t + 1):
            fac = factorize(num, spf)
            for p, exp in fac.items():
                prime_exp[p] = prime_exp.get(p, 0) + exp

        # Subtract exponents for ca!
        for num in range(1, ca + 1):
            fac = factorize(num, spf)
            for p, exp in fac.items():
                prime_exp[p] = prime_exp.get(p, 0) - exp

        # Subtract exponents for cb!
        for num in range(1, cb + 1):
            fac = factorize(num, spf)
            for p, exp in fac.items():
                prime_exp[p] = prime_exp.get(p, 0) - exp

        i = j

    # Compute result from prime_exp
    result = 1
    for prime, exp in prime_exp.items():
        if exp > 0:
            result = (result * pow(prime, exp, m)) % m

    print(result % m)

if __name__ == "__main__":
    main()

