def solve() -> None:
    n = int(sys.stdin.readline().strip())

    # Number of ways to choose groups of size 5, 6, and 7 from n people
    # C(n, k) = n! / (k! * (n - k)!)

    # Helper function for binomial coefficient using multiplicative formula
    def binom_coeff(N: int, K: int) -> int:
        if K < 0 or K > N:
            return 0
        if K == 0 or K == N:
            return 1
        K = min(K, N - K)  # Use symmetry
        res = 1
        for i in range(1, K + 1):
            res = res * (N - K + i) // i
        return res

    total = binom_coeff(n, 5) + binom_coeff(n, 6) + binom_coeff(n, 7)
    print(total)

