import sys

MOD = 10**9 + 7
MAXN = 10**5

# Precompute factorials and inverse factorials modulo MOD
fact = [1] * (MAXN + 1)
inv_fact = [1] * (MAXN + 1)

for i in range(1, MAXN + 1):
    fact[i] = fact[i-1] * i % MOD

def mod_pow(a, b, mod):
    res = 1
    while b:
        if b & 1:
            res = res * a % mod
        a = a * a % mod
        b >>= 1
    return res

inv_fact[MAXN] = mod_pow(fact[MAXN], MOD-2, MOD)
for i in range(MAXN-1, -1, -1):
    inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

def nCr(n, r):
    if r < 0 or r > n:
        return 0
    return fact[n] * inv_fact[r] % MOD * inv_fact[n-r] % MOD

# Precompute mobius function up to MAXN using linear sieve
mobius = [1] * (MAXN + 1)
primes = []
is_composite = [False] * (MAXN + 1)

mobius[1] = 1
for i in range(2, MAXN + 1):
    if not is_composite[i]:
        primes.append(i)
        mobius[i] = -1
    for p in primes:
        if i * p > MAXN:
            break
        is_composite[i * p] = True
        if i % p == 0:
            mobius[i * p] = 0
            break
        else:
            mobius[i * p] = -mobius[i]

