        n = int(data[idx]); f = int(data[idx+1]); idx += 2
        if f == 1:
            out_lines.append("1" if n == 1 else "0")
            continue
        ans = 0
        # iterate over divisors d of n
        d = 1
        while d * d <= n:
            if n % d == 0:
                d1 = d
                d2 = n // d
                for d_val in (d1, d2):
                    if d_val == 1:
                        continue
                    if n // d_val >= f:
                        ways = nCr(n // d_val - 1, f - 1)
                        if mobius[d_val] == 1:
