import sys

MOD = 10**9 + 7
MAXN = 10**5

# Precompute factorials and inverse factorials modulo MOD
fact = [1] * (MAXN + 1)
inv_fact = [1] * (MAXN + 1)

for i in range(1, MAXN + 1):
    fact[i] = fact[i-1] * i % MOD

def mod_pow(a, b, mod):
    res = 1
    while b:
        if b & 1:
            res = res * a % mod
        a = a * a % mod
        b >>= 1
    return res

inv_fact[MAXN] = mod_pow(fact[MAXN], MOD-2, MOD)
for i in range(MAXN-1, -1, -1):
    inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

def nCr(n, r):
    if r < 0 or r > n:
        return 0
    return fact[n] * inv_fact[r] % MOD * inv_fact[n-r] % MOD

# Precompute mobius function up to MAXN using linear sieve
mobius = [1] * (MAXN + 1)
primes = []
is_composite = [False] * (MAXN + 1)

mobius[1] = 1
for i in range(2, MAXN + 1):
    if not is_composite[i]:
        primes.append(i)
        mobius[i] = -1
    for p in primes:
        if i * p > MAXN:
            break
        is_composite[i * p] = True
        if i % p == 0:
            mobius[i * p] = 0
            break
        else:
            mobius[i * p] = -mobius[i]

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    q = int(data[0])
    out_lines = []
    idx = 1
    for _ in range(q):
        n = int(data[idx]); f = int(data[idx+1]); idx += 2
        if f == 1:
            out_lines.append("1" if n == 1 else "0")
            continue
        ans = 0
        # iterate over divisors d of n
        d = 1
        while d * d <= n:
            if n % d == 0:
                d1 = d
                d2 = n // d
                for d_val in (d1, d2):
                    if d_val == 1:
                        continue
                    if n // d_val >= f:
                        ways = nCr(n // d_val - 1, f - 1)
                        if mobius[d_val] == 1:
                            ans = (ans + ways) % MOD
                        elif mobius[d_val] == -1:
                            ans = (ans - ways) % MOD
            d += 1
        # Adjust for the case where d1 == d2 (square number) counted twice
        # Actually our loop avoids double counting by checking d_val each time,
        # but we still need to ensure we don't count d=1 (handled above).
        out_lines.append(str(ans % MOD))
    sys.stdout.write("\n".join(out_lines))

