import sys
from collections import defaultdict, deque

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    parents = list(map(int, data[1:]))

    children = defaultdict(list)
    for i, p in enumerate(parents, start=2):
        children[p].append(i)

    leaves = [0] * (n + 1)

    # process from leaves to root
    order = []
    queue = deque([1])
    while queue:
        v = queue.popleft()
        order.append(v)
        for ch in children[v]:
            queue.append(ch)

    for v in reversed(order):
        if not children[v]:
            leaves[v] = 1
        else:
            leaves[v] = sum(leaves[ch] for ch in children[v])

    freq = [0] * (n + 1)
    for i in range(1, n + 1):
        freq[leaves[i]] += 1

    ans = []
    colors = 1
    satisfied = 0

    for k in range(1, n + 1):
        while satisfied < k:
            if freq[colors] > 0:
                satisfied += 1
                freq[colors] -= 1
            else:
                colors += 1
        ans.append(colors)

    print(' '.join(map(str, ans)))

if __name__ == "__main__":
