import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    W = [[0.0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            W[i][j] = float(next(it))

    A = [[0.0] * n for _ in range(n)]
    B = [[0.0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if i == j:
                A[i][j] = W[i][j]
                B[i][j] = 0.0
            else:
                # Use the given conditions:
                # A[i][j] = A[j][i] = (W[i][j] + W[j][i]) / 2
                # B[i][j] = -B[j][i] = (W[i][j] - W[j][i]) / 2
                sym = (W[i][j] + W[j][i]) / 2.0
                antisym = (W[i][j] - W[j][i]) / 2.0
                A[i][j] = sym
                A[j][i] = sym
                B[i][j] = antisym
                B[j][i] = -antisym

    # Output A
    for i in range(n):
        print(' '.join(f'{A[i][j]:.8f}' for j in range(n)))
    # Output B
    for i in range(n):
        print(' '.join(f'{B[i][j]:.8f}' for j in range(n)))

if __name__ == "__main__":
    solve()

