    input_data = sys.stdin.read().split()
    n = int(input_data[0])
    m = int(input_data[1])
    s = list(input_data[2])

    # count initial number of ".." occurrences
    count = 0
    for i in range(n - 1):
        if s[i] == '.' and s[i + 1] == '.':
            count += 1

    out_lines = []
    idx = 3
    for _ in range(m):
        pos = int(input_data[idx]) - 1  # 0‑based
        ch = input_data[idx + 1]
        idx += 2

        old_char = s[pos]
        if old_char == ch:
            out_lines.append(str(count))
            continue

        # remove contributions of the old char around pos
        if old_char == '.':
            if pos > 0 and s[pos - 1] == '.':
                count -= 1
            if pos + 1 < n and s[pos + 1] == '.':
                count -= 1

        # add contributions of the new char around pos
        if ch == '.':
            if pos > 0 and s[pos - 1] == '.':
                count += 1
            if pos + 1 < n and s[pos + 1] == '.':
                count += 1

        s[pos] = ch
        out_lines.append(str(count))

    sys.stdout.write("\n".join(out_lines))

