MOD = 10**9 + 7

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    cost = [int(next(it)) for _ in range(n)]
    m = int(next(it))
    adj = [[] for _ in range(n)]
    radj = [[] for _ in range(n)]
    for _ in range(m):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        adj[u].append(v)
        radj[v].append(u)

    # Kosaraju's algorithm for SCCs
    visited = [False] * n
    order = []

    def dfs1(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

    for i in range(n):
        if not visited[i]:
            dfs1(i)

    comp = [-1] * n
    current_comp = 0

    def dfs2(u):
        stack = [u]
        while stack:
            node = stack.pop()
            if comp[node] != -1:
                continue
            comp[node] = current_comp
            for v in radj[node]:
                if comp[v] == -1:
                    stack.append(v)

    for u in reversed(order):
        if comp[u] == -1:
            dfs2(u)
            current_comp += 1

    # For each SCC, find min cost and count
    comp_min = [10**18] * current_comp
    comp_cnt = [0] * current_comp

    for i in range(n):
        cid = comp[i]
        if cost[i] < comp_min[cid]:
            comp_min[cid] = cost[i]
            comp_cnt[cid] = 1
        elif cost[i] == comp_min[cid]:
            comp_cnt[cid] += 1

    total_cost = 0
    total_ways = 1
    for i in range(current_comp):
        total_cost += comp_min[i]
        total_ways = (total_ways * comp_cnt[i]) % MOD

    print(total_cost, total_ways)


