import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, a, b = map(int, data)
    # Ensure a < b for easier processing
    if a > b:
        a, b = b, a
    round_num = 1
    while n > 1:
        # Check if a and b are paired in this round
        if (a % 2 == 1) and (b == a + 1):
            if n == 2:
                print("Final!")
            else:
                print(round_num)
            return
        # Move to next round
        a = (a + 1) // 2
        b = (b + 1) // 2
