        # Check if a and b are paired in this round
        if (a % 2 == 1) and (b == a + 1):
            if n == 2:
                print("Final!")
            else:
                print(round_num)
            return
        # Move to next round
        a = (a + 1) // 2
        b = (b + 1) // 2
        n //= 2
        round_num += 1

