import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    A = [[0] * m for _ in range(n)]
    B = [[0] * m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            A[i][j] = int(next(it))

    for i in range(n):
        for j in range(m):
            B[i][j] = int(next(it))

    # For each cell, we want the smaller value in A and larger in B
    # but both matrices must end up increasing.
    # We can always swap to put min(a,b) in A and max(a,b) in B,
    # because swapping back later is always possible if needed.
    # After fixing each cell like that, we just check if both matrices are increasing.

    for i in range(n):
        for j in range(m):
            x, y = A[i][j], B[i][j]
            if x > y:
                A[i][j], B[i][j] = y, x

    # Check rows and columns for strictly increasing property
    def check_matrix(M):
        for i in range(n):
            for j in range(m - 1):
                if M[i][j] >= M[i][j + 1]:
                    return False
        for j in range(m):
            for i in range(n - 1):
                if M[i][j] >= M[i + 1][j]:
                    return False
        return True

    if check_matrix(A) and check_matrix(B):
        print("Possible")
    else:
        print("Impossible")

