# Precomputed lengths for f_n up to n where length exceeds 10^18
MAX_N = 10**5
MAX_K = 10**18

# Base string f0
f0 = "What are you doing at the end of the world? Are you busy? Will you save us?"
len_f0 = len(f0)

# Prefix and suffix strings
prefix = "What are you doing while sending \""
suffix = "\"? Are you busy? Will you send \""
ending = "\"?"

len_prefix = len(prefix)
len_suffix = len(suffix)
len_ending = len(ending)

# Precompute lengths
lengths = [0] * (MAX_N + 5)
lengths[0] = len_f0
for i in range(1, MAX_N + 5):
    # f_i = prefix + f_{i-1} + suffix + f_{i-1} + ending
    # Check for overflow: if f_{i-1} already >= MAX_K, then f_i will be huge.
    if lengths[i-1] >= MAX_K:
        lengths[i] = MAX_K + 1  # Anything > MAX_K works, we just need "too big"
    else:
        total = len_prefix + lengths[i-1] + len_suffix + lengths[i-1] + len_ending
        if total > MAX_K:
            lengths[i] = MAX_K + 1
        else:
            lengths[i] = total

def get_char(n, k):
    # k is 1‑based
    while True:
        if n == 0:
            if k <= len_f0:
                return f0[k-1]
            else:
                return '.'
        # n >= 1
        # Structure: prefix + f_{n-1} + suffix + f_{n-1} + ending
        if k <= len_prefix:
            return prefix[k-1]
        k -= len_prefix
        if k <= lengths[n-1]:
            n -= 1
            continue  # inside first f_{n-1}
        k -= lengths[n-1]
        if k <= len_suffix:
            return suffix[k-1]
        k -= len_suffix
        if k <= lengths[n-1]:
            n -= 1
            continue  # inside second f_{n-1}
        k -= lengths[n-1]
        if k <= len_ending:
            return ending[k-1]
        return '.'

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    q = int(data[0])
    idx = 1
    out_chars = []
    for _ in range(q):
        n = int(data[idx]); k = int(data[idx+1])
        idx += 2
        out_chars.append(get_char(n, k))
    sys.stdout.write(''.join(out_chars))

if __name__ == "__main__":
    main()

