import sys
from collections import defaultdict
import math

MOD = 10**9 + 7

def factorize(x):
    factors = defaultdict(int)
    d = 2
    while d * d <= x:
        while x % d == 0:
            factors[d] += 1
            x //= d
        d += 1 if d == 2 else 2
    if x > 1:
        factors[x] += 1
    return factors

def modinv(a, p=MOD):
    # Fermat's for prime MOD
    return pow(a, p-2, p)

def main():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    n = int(input_data[0])
    arr = list(map(int, input_data[1:1+n]))

    # Combine prime factors of m
    total_factors = defaultdict(int)
    for num in arr:
        fac = factorize(num)
        for p, exp in fac.items():
            total_factors[p] += exp

    # Precompute factorials and inverse factorials up to max needed
    max_exp = max(total_factors.values()) if total_factors else 0
    max_n = n + max_exp  # we need factorials up to n + max_exp
    fact = [1] * (max_n + 2)
    inv_fact = [1] * (max_n + 2)
    for i in range(2, max_n + 2):
        fact[i] = fact[i-1] * i % MOD
    inv_fact[max_n + 1] = modinv(fact[max_n + 1])
    for i in range(max_n, -1, -1):
        inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

    def comb(a, b):
        if b < 0 or b > a:
            return 0
        return fact[a] * inv_fact[b] % MOD * inv_fact[a-b] % MOD

    ans = 1
    for exp in total_factors.values():
        ans = ans * comb(exp + n - 1, n - 1) % MOD

    print(ans % MOD)

if __name__ == "__main__":
    main()

