    n = len(x_str)
    x = int(x_str, 2)

    memo = {}

    def inv(x, n):
        if n == 1:
            return x % MOD  # x is 0 or 1
        key = (x, n)
        if key in memo:
            return memo[key]
        h = 1 << (n - 1)
        if x & h:
            y = x ^ h
            res = (2 * inv(y, n - 1) + (1 << (2 * (n - 1)))) % MOD
        else:
            res = (2 * inv(x, n - 1)) % MOD
        memo[key] = res
        return res

    print(inv(x, n))

