import sys

def is_vowel(ch: str) -> bool:
    return ch in 'aeiouy'

def count_syllables_in_word(word: str) -> int:
    count = 0
    i = 0
    while i < len(word):
        if is_vowel(word[i]):
            count += 1
            # skip until next consonant or end
            i += 1
            while i < len(word) and is_vowel(word[i]):
                i += 1
        else:
            i += 1
    return count

def count_syllables_in_line(line: str) -> int:
    words = line.split()
    total = 0
    for w in words:
        # a word with no vowel contributes 0
        if any(is_vowel(ch) for ch in w):
            total += count_syllables_in_word(w)
    return total

def main() -> None:
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n = int(data[0].strip())
    pattern = list(map(int, data[1].split()))
    lines = data[2:2+n]

    if len(pattern) != n or len(lines) != n:
        print("NO")
        return

    for i in range(n):
        if count_syllables_in_line(lines[i]) != pattern[i]:
            print("NO")
            return
    print("YES")

if __name__ == "__main__":
