def solve():
    n = int(input().strip())
    s = input().strip()
    m = len(s)

    # Build automaton: automaton[k][0] = next matched length if char '('
    #                 automaton[k][1] = next matched length if char ')'
    automaton = [[0, 0] for _ in range(m + 1)]

    for k in range(m + 1):
        for ch in ('(', ')'):
            # Try to match s[:k] + ch
            now = s[:k] + ch
            for nxt in range(min(k + 1, m), -1, -1):
                if now.endswith(s[:nxt]):
                    if ch == '(':
                        automaton[k][0] = nxt
                    else:
                        automaton[k][1] = nxt
                    break

    # DP: dp[pos][balance][matched][found]
    # pos: 0..2n, balance: 0..n, matched: 0..m, found: 0/1
    dp = [[[[0] * 2 for _ in range(m + 1)] for _ in range(n + 1)] for _ in range(2 * n + 1)]
    dp[0][0][0][0] = 1

    for pos in range(2 * n):
        for balance in range(n + 1):
            for matched in range(m + 1):
                for found in range(2):
                    cur = dp[pos][balance][matched][found]
                    if cur == 0:
                        continue
                    # Try '('
                    if balance + 1 <= n:
                        nxt_matched = automaton[matched][0]
                        nxt_found = found or (nxt_matched == m)
                        dp[pos + 1][balance + 1][nxt_matched][nxt_found] = (dp[pos + 1][balance + 1][nxt_matched][nxt_found] + cur) % MOD
                    # Try ')'
                    if balance - 1 >= 0:
                        nxt_matched = automaton[matched][1]
                        nxt_found = found or (nxt_matched == m)
                        dp[pos + 1][balance - 1][nxt_matched][nxt_found] = (dp[pos + 1][balance - 1][nxt_matched][nxt_found] + cur) % MOD

    ans = 0
    for matched in range(m + 1):
        ans = (ans + dp[2 * n][0][matched][1]) % MOD
    print(ans)

if __name__ == "__main__":
    solve()

