import sys

def main() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = int(data[0])
    L = list(map(int, data[1:1+N]))
    L.sort()

    ans = 0
    for i in range(N - 2):
        for j in range(i + 1, N - 1):
            # Binary search for the largest k where L[i] + L[j] > L[k]
            left, right = j + 1, N - 1
            k = j  # default if none found
            while left <= right:
                mid = (left + right) // 2
                if L[i] + L[j] > L[mid]:
                    k = mid
                    left = mid + 1
                else:
                    right = mid - 1
            ans += k - j
    print(ans)

if __name__ == "__main__":
    main()

