import sys
sys.setrecursionlimit(1000000)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    s = int(next(it)) - 1  # 0-based indexing

    graph = [[] for _ in range(n)]
    reverse_graph = [[] for _ in range(n)]

    for _ in range(m):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        graph[u].append(v)
        reverse_graph[v].append(u)

    # Step 1: find all nodes reachable from s
    visited = [False] * n
    stack = [s]
    visited[s] = True
    while stack:
        u = stack.pop()
        for v in graph[u]:
            if not visited[v]:
                visited[v] = True
                stack.append(v)

    # If all cities are reachable, print 0
    if all(visited):
        print(0)
        return

    # Step 2: find SCCs using Kosaraju's algorithm
    order = []
    def dfs1(u):
        visited1[u] = True
        for v in graph[u]:
            if not visited1[v]:
                dfs1(v)
        order.append(u)

    visited1 = [False] * n
    for i in range(n):
        if not visited1[i]:
            dfs1(i)

    comp = [-1] * n
    def dfs2(u, label):
        comp[u] = label
        for v in reverse_graph[u]:
            if comp[v] == -1:
                dfs2(v, label)

    label = 0
    for u in reversed(order):
        if comp[u] == -1:
            dfs2(u, label)
            label += 1

    # Step 3: build condensation DAG
    in_degree = [0] * label
    for u in range(n):
        for v in graph[u]:
            if comp[u] != comp[v]:
                in_degree[comp[v]] += 1

    # Step 4: count SCCs with zero in-degree and not reachable from s
    reachable_comps = set()
    for i in range(n):
        if visited[i]:
            reachable_comps.add(comp[i])

    ans = 0
    for c in range(label):
        if in_degree[c] == 0 and c not in reachable_comps:
            ans += 1

    print(ans)

if __name__ == "__main__":
    solve()
