import sys

def is_prime(num):
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    i = 3
    while i * i <= num:
        if num % i == 0:
            return False
        i += 2
    return True

def is_palindrome(num):
    s = str(num)
    return s == s[::-1]

def solve():
    p, q = map(int, sys.stdin.readline().split())
    # Precompute prime and palindrome counts up to a large enough limit
    # From the problem constraints, p/q ≤ 42, so π(n) ≤ 42 * rub(n)
    # rub(n) grows very slowly (approx O(sqrt(n))), so π(n) grows faster.
    # We can try up to a few million. In competitive programming, 2*10^6 is safe.
    LIMIT = 2000000
    prime_count = [0] * (LIMIT + 1)
    palin_count = [0] * (LIMIT + 1)

    prime_total = 0
    palin_total = 0
    for i in range(1, LIMIT + 1):
        if is_prime(i):
            prime_total += 1
        if is_palindrome(i):
            palin_total += 1
        prime_count[i] = prime_total
        palin_count[i] = palin_total

    ans = -1
    for i in range(1, LIMIT + 1):
        if prime_count[i] * q <= p * palin_count[i]:
            ans = i
    if ans == -1:
        print("Palindromic tree is better than splay tree")
    else:
        print(ans)

if __name__ == "__main__":
    solve()
