def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    s = list(data[2])

    changes = 0

    # First digit: if n > 1, we must avoid leading zero
    if n > 1:
        if s[0] != '1' and changes < k:
            s[0] = '1'
            changes += 1
    else:
        # n == 1, we can change to 0 if k >= 1
        if k >= 1:
            s[0] = '0'
        print(''.join(s))
