import sys

sys.setrecursionlimit(300000)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    a = [0] * n
    for i in range(n):
        a[i] = int(next(it))

    edges = []
    # Special offers
    for _ in range(m):
        x = int(next(it)) - 1
        y = int(next(it)) - 1
        w = int(next(it))
        edges.append((w, x, y))

    # Connect every vertex to the one with minimal a[i] using normal cost
    min_idx = 0
    for i in range(1, n):
        if a[i] < a[min_idx]:
            min_idx = i
    for i in range(n):
        if i != min_idx:
            cost = a[i] + a[min_idx]
            edges.append((cost, i, min_idx))

    # Kruskal's algorithm
    parent = list(range(n))
    rank = [0] * n

    def find(v):
        while parent[v] != v:
            parent[v] = parent[parent[v]]
            v = parent[v]
        return v

    def union(v1, v2):
        r1, r2 = find(v1), find(v2)
        if r1 == r2:
            return False
        if rank[r1] < rank[r2]:
            parent[r1] = r2
        elif rank[r1] > rank[r2]:
            parent[r2] = r1
        else:
            parent[r2] = r1
            rank[r1] += 1
        return True

    edges.sort()
    total = 0
    components = n
    for w, u, v in edges:
        if union(u, v):
            total += w
            components -= 1
            if components == 1:
                break

    print(total)

if __name__ == "__main__":
