    primes_with_2 = [2] + primes

    # Case 1: p^3 * q (p, q odd primes, p != q)
    # p^3 must be ≤ 200
    for p in primes:
        p3 = p ** 3
        if p3 > 200:
            break
        for q in primes:
            if q == p:
                continue
            if p3 * q > N:
                break
            count += 1

