import sys

def solve():
    input = sys.stdin.read
    data = input().split()
    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1

    a = [0] * n
    for i in range(n):
        a[i] = int(data[idx]); idx += 1

    edges = []
    for _ in range(m):
        x = int(data[idx]) - 1; idx += 1
        y = int(data[idx]) - 1; idx += 1
        w = int(data[idx]); idx += 1
        edges.append((w, x, y))

    # Find vertex with minimum a[i]
    min_idx = 0
    for i in range(1, n):
        if a[i] < a[min_idx]:
            min_idx = i

    # Add edges from min_idx to all other vertices with cost a[min_idx] + a[j]
    for j in range(n):
        if j != min_idx:
            edges.append((a[min_idx] + a[j], min_idx, j))

    # Kruskal's algorithm
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        xroot = find(x)
        yroot = find(y)
        if xroot == yroot:
            return False
        if rank[xroot] < rank[yroot]:
            parent[xroot] = yroot
        elif rank[xroot] > rank[yroot]:
            parent[yroot] = xroot
        else:
            parent[yroot] = xroot
            rank[xroot] += 1
        return True

    edges.sort()
    total_cost = 0
    edges_used = 0

    for w, u, v in edges:
        if union(u, v):
            total_cost += w
            edges_used += 1
            if edges_used == n - 1:
                break

    print(total_cost)

if __name__ == "__main__":
    solve()

