import sys
sys.setrecursionlimit(300000)

def solve():
    n, m = map(int, sys.stdin.readline().split())
    adj = [[] for _ in range(n)]
    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        u -= 1
        v -= 1
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * n
    is_cycle = True

    def dfs(u, parent):
        nonlocal is_cycle
        visited[u] = True
        # For a cycle component, each vertex must have exactly 2 edges in the component
        if len(adj[u]) != 2:
            is_cycle = False
        for v in adj[u]:
            if not visited[v]:
                dfs(v, u)
            elif v != parent:
                # This detects a back edge, but we only care after full component check
                pass

    cycles = 0
    for i in range(n):
        if not visited[i]:
            is_cycle = True
            dfs(i, -1)
            if is_cycle:
                cycles += 1
    print(cycles)

if __name__ == "__main__":
    solve()

