import sys
sys.setrecursionlimit(300000)

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    graph = [[] for _ in range(n)]
    degree = [0] * n

    for _ in range(m):
        a = int(next(it)) - 1
        b = int(next(it)) - 1
        graph[a].append(b)
        graph[b].append(a)
        degree[a] += 1
        degree[b] += 1

    visited = [False] * n

    def dfs(v: int) -> bool:
        stack = [v]
        is_cycle = True
        vertices_count = 0
        while stack:
            cur = stack.pop()
            if visited[cur]:
                continue
            visited[cur] = True
            vertices_count += 1
            if degree[cur] != 2:
                is_cycle = False
            for nb in graph[cur]:
                if not visited[nb]:
                    stack.append(nb)
        return is_cycle and vertices_count >= 3

    answer = 0
    for i in range(n):
        if not visited[i]:
            if dfs(i):
                answer += 1

    print(answer)

if __name__ == "__main__":
    solve()

