def solve():
    t = int(sys.stdin.readline())
    out_lines = []
    for _ in range(t):
        L, v, l, r = map(int, sys.stdin.readline().split())
        total = L // v
        # Lanterns blocked by the standing train
        # First blocked lantern position >= l and divisible by v
        first_blocked = l + ((v - l % v) % v)
        if first_blocked > r:
            blocked = 0
        else:
            last_blocked = r - (r % v)
            if last_blocked < first_blocked:
                blocked = 0
            else:
                blocked = (last_blocked - first_blocked) // v + 1
        out_lines.append(str(total - blocked))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

