def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    h = int(data[0])
    w = int(data[1])
    grid = data[2:2 + h]

    # Find the center candidate: a '*' that has '*' in all four directions
    center_i, center_j = -1, -1
    found_center = False

    for i in range(1, h - 1):
        for j in range(1, w - 1):
            if (grid[i][j] == '*' and
                grid[i-1][j] == '*' and
                grid[i+1][j] == '*' and
                grid[i][j-1] == '*' and
                grid[i][j+1] == '*'):
                # Potential center found
                center_i, center_j = i, j
                found_center = True
                break
        if found_center:
            break

    if not found_center:
        print("NO")
        return

    # Check that all rays consist only of '*' without gaps
    # Up
    up_len = 0
    for k in range(center_i - 1, -1, -1):
        if grid[k][center_j] == '*':
            up_len += 1
        else:
            break
    # Down
    down_len = 0
    for k in range(center_i + 1, h):
        if grid[k][center_j] == '*':
            down_len += 1
        else:
            break
    # Left
    left_len = 0
    for k in range(center_j - 1, -1, -1):
        if grid[center_i][k] == '*':
            left_len += 1
        else:
            break
    # Right
    right_len = 0
    for k in range(center_j + 1, w):
        if grid[center_i][k] == '*':
            right_len += 1
        else:
            break

    # Each ray must have at least one cell
    if up_len == 0 or down_len == 0 or left_len == 0 or right_len == 0:
        print("NO")
        return

    # Mark all cells belonging to the plus as visited
    # We'll use a set or a 2D list to mark them
    visited = [[False] * w for _ in range(h)]

    # Mark center
    visited[center_i][center_j] = True

    # Mark up
    for k in range(center_i - up_len, center_i):
        visited[k][center_j] = True
    # Mark down
    for k in range(center_i + 1, center_i + down_len + 1):
        visited[k][center_j] = True
    # Mark left
    for k in range(center_j - left_len, center_j):
        visited[center_i][k] = True
    # Mark right
    for k in range(center_j + 1, center_j + right_len + 1):
        visited[center_i][k] = True

    # Now check: every '*' in grid must be visited, and every visited must be '*'
    for i in range(h):
        for j in range(w):
            if grid[i][j] == '*' and not visited[i][j]:
                print("NO")
                return
            if visited[i][j] and grid[i][j] != '*':
                print("NO")
                return

    print("YES")

