import sys

def solve() -> None:
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    h, w = map(int, data[0].split())
    grid = data[1:]

    # Find all '*' cells
    stars = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == '*':
                stars.append((i, j))

    # If there are no stars, it's not a plus
    if not stars:
        print("NO")
        return

    # Try every star as a possible center
    for ci, cj in stars:
        # Check that the center itself is '*'
        if grid[ci][cj] != '*':
            continue

        # Check arms length at least 1 in each direction
        up_len = 0
        while ci - up_len - 1 >= 0 and grid[ci - up_len - 1][cj] == '*':
            up_len += 1

        down_len = 0
        while ci + down_len + 1 < h and grid[ci + down_len + 1][cj] == '*':
            down_len += 1

        left_len = 0
        while cj - left_len - 1 >= 0 and grid[ci][cj - left_len - 1] == '*':
            left_len += 1

        right_len = 0
        while cj + right_len + 1 < w and grid[ci][cj + right_len + 1] == '*':
            right_len += 1

        # Need at least one cell in each direction
        if up_len == 0 or down_len == 0 or left_len == 0 or right_len == 0:
            continue

        # All cells in the plus shape
        plus_cells = set()
        plus_cells.add((ci, cj))
        for k in range(1, up_len + 1):
            plus_cells.add((ci - k, cj))
        for k in range(1, down_len + 1):
            plus_cells.add((ci + k, cj))
        for k in range(1, left_len + 1):
            plus_cells.add((ci, cj - k))
        for k in range(1, right_len + 1):
            plus_cells.add((ci, cj + k))

        # Check if all stars in the grid are exactly those in plus_cells
        if len(stars) != len(plus_cells):
            continue

        ok = True
        for sr, sc in stars:
            if (sr, sc) not in plus_cells:
                ok = False
                break
        if ok:
            print("YES")
            return

    print("NO")

if __name__ == "__main__":
    solve()
