    # Convert date to total days from a fixed point, e.g., 1900-01-01 = day 0
    total = 0
    # Add years
    for year in range(1900, y):
        total += 366 if is_leap(year) else 365
    # Add months
    for month in range(1, m):
        total += days_in_month(y, month)
    # Add days
    total += d - 1  # because we want 1900-01-01 to be day 0
    return total

