import sys

def is_leap_year(year: int) -> bool:
    """Return True if year is a Gregorian leap year."""
    return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)

def days_in_month(year: int, month: int) -> int:
    """Return number of days in given month of given year."""
    if month == 2:
        return 29 if is_leap_year(year) else 28
    if month in (4, 6, 9, 11):
        return 30
    return 31

def date_to_days(year: int, month: int, day: int) -> int:
    """Convert a date to number of days since 1900-01-01 (inclusive)."""
    total = 0
    # Add days for full years before the given year
    for y in range(1900, year):
        total += 366 if is_leap_year(y) else 365
    # Add days for full months in the current year
    for m in range(1, month):
        total += days_in_month(year, m)
    # Add days in the current month
    total += day
    return total

def main() -> None:
    data = sys.stdin.read().strip().split()
    if len(data) != 2:
        return
    y1, m1, d1 = map(int, data[0].split(':'))
    y2, m2, d2 = map(int, data[1].split(':'))

    days1 = date_to_days(y1, m1, d1)
    days2 = date_to_days(y2, m2, d2)

    print(abs(days1 - days2))

if __name__ == "__main__":
