import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    wins = list(map(int, data[1:1 + n]))

    # Valid start: Alex and Bob play, Carl spectates
    spectators = {3}  # set of possible spectators after 0 games
    players = {1, 2}  # set of possible players after 0 games

    possible = True
    for w in wins:
        if w not in players:
            possible = False
            break
        # The loser becomes spectator, the previous spectator joins
        # New players are: {winner, previous_spectator}
        # New spectator is: the loser (3 - (sum of new players))
        # Since loser = the other player from previous players
        loser = (players - {w}).pop()
        prev_spectator = spectators.pop()
        players = {w, prev_spectator}
        spectators = {loser}

    print("YES" if possible else "NO")

if __name__ == "__main__":
    solve()

