import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    p = float(data[1])
    t = int(data[2])

    # dp[i][j] = probability that after i seconds, j people are on escalator
    # i from 0..t, j from 0..n
    dp = [[0.0] * (n + 1) for _ in range(t + 1)]
    dp[0][0] = 1.0

    for time in range(1, t + 1):
        for people in range(n + 1):
            if people == n:
                # all people already on, cannot add more
                dp[time][people] += dp[time - 1][people]
            else:
                # we can add one person with prob p
                dp[time][people] += dp[time - 1][people] * (1.0 - p)
                if people > 0:
                    dp[time][people] += dp[time - 1][people - 1] * p
        # Note: if people == 0 and time > 0, only (1-p) term applies

    expected = 0.0
    for people in range(n + 1):
        expected += people * dp[t][people]

    print("{:.15f}".format(expected))

if __name__ == "__main__":
    solve()

