def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    arr = list(map(int, data[1:1 + n]))

    MAX_VAL = 10**6
    freq = [0] * (MAX_VAL + 1)
    for x in arr:
        freq[x] = 1

    # dp[i] = size of largest clique where i is the largest element (in value)
    dp = [0] * (MAX_VAL + 1)

    for i in range(1, MAX_VAL + 1):
        if freq[i]:
            dp[i] = max(dp[i], 1)
            # iterate over multiples of i
            for multiple in range(2 * i, MAX_VAL + 1, i):
                if freq[multiple]:
                    dp[multiple] = max(dp[multiple], dp[i] + 1)

    # answer is the maximum in dp
    ans = max(dp) if dp else 0
    print(ans)

if __name__ == "__main__":
    main()

