import sys

def solve() -> None:
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n, m = map(int, data[0].split())
    table = [list(line.strip()) for line in data[1:1+n]]

    removed = 0
    good_prefix = [True] * n  # rows are already "good" initially (empty prefix)
    # We'll check column by column
    for col in range(m):
        # Check if we can keep this column without breaking lexicographic order
        can_keep = True
        for row in range(1, n):
            if not good_prefix[row]:
                # If rows are already distinguished earlier, this column doesn't matter
                continue
            if table[row][col] < table[row-1][col]:
                # Would break order, must remove this column
                can_keep = False
                break
        if not can_keep:
            removed += 1
        else:
            # Mark which rows become distinguished because of this column
            for row in range(1, n):
                if good_prefix[row] and table[row][col] > table[row-1][col]:
                    good_prefix[row] = False  # now this row is strictly greater than previous
    print(removed)

if __name__ == "__main__":
