def solve() -> None:
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n, m = map(int, data[0].split())
    grid = [list(row.strip()) for row in data[1:1 + n]]

    # We'll check the property:
    # For any two black cells (r1, c1) and (r2, c2),
    # the cells (r1, c2) and (r2, c1) must also be black.
    # This is the necessary and sufficient condition for
    # the described row/column selection process.
    for r1 in range(n):
        for c1 in range(m):
            if grid[r1][c1] == '#':
                for r2 in range(r1 + 1, n):
                    for c2 in range(c1 + 1, m):
                        if grid[r2][c2] == '#':
                            if grid[r1][c2] != '#' or grid[r2][c1] != '#':
                                print("No")
                                return
    print("Yes")

if __name__ == "__main__":
    solve()

