def solve():
    n, k, M, D = map(int, input().split())
    ans = 0
    for m in range(1, D + 1):
        if 1 + k * (m - 1) > n:
            break
        x_high = n // (1 + k * (m - 1))
        x_low = n // (k * m + 1) + 1
        candidate_x = min(M, x_high)
        if candidate_x >= x_low:
            ans = max(ans, m * candidate_x)
    print(ans)

if __name__ == "__main__":
    solve()

