import sys

def main():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n, m = map(int, data[0].split())
    grid = data[1:1+n]

    heights = []
    for col in range(m):
        h = 0
        # find the highest '*' in this column (lowest row index = top)
        for row in range(n):
            if grid[row][col] == '*':
                h = n - row  # height from bottom
                break
        heights.append(h)

    max_up = 0
    max_down = 0
    for i in range(1, len(heights)):
        diff = heights[i] - heights[i-1]
        if diff > 0:
            max_up = max(max_up, diff)
        elif diff < 0:
            max_down = max(max_down, -diff)

    print(f"{max_up} {max_down}")

if __name__ == "__main__":
    main()
