def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1 + n]))

    # seen[x] will be the smallest index (1-based) where x appears,
    # or 0 if not yet seen.
    seen = dict()

    for i, val in enumerate(a, start=1):
        if val not in seen:
            seen[val] = i
        # Check if the current value is impossible
        # For val to be possible, val-1 must have appeared earlier.
        if val > 0:
            prev_idx = seen.get(val - 1, 0)
            if prev_idx == 0 or prev_idx >= i:
                print(i)
                return
    print(-1)

if __name__ == "__main__":
    solve()

