import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    f = [0] * n
    for i in range(n):
        f[i] = int(next(it))

    b = [0] * m
    for i in range(m):
        b[i] = int(next(it))

    # positions[f_value] = list of indices (1‑based) in f
    positions = [[] for _ in range(n + 1)]
    for idx, val in enumerate(f, start=1):
        positions[val].append(idx)

    a = [0] * m
    possible = True
    ambiguous = False

    for i in range(m):
        val = b[i]
        lst = positions[val]
        if not lst:
            possible = False
            break
        if len(lst) > 1:
            ambiguous = True
        a[i] = lst[0]  # choose any, we just need existence for now

    if not possible:
        print("Impossible")
    elif ambiguous:
        print("Ambiguity")
    else:
        print("Possible")
        print(' '.join(map(str, a)))

if __name__ == "__main__":
    solve()

