import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    c = list(map(int, data[1:1 + n]))

    # compress consecutive duplicates
    a = []
    for color in c:
        if not a or color != a[-1]:
            a.append(color)
    m = len(a)

    # dp[l][r] = minimum turns to turn interval [l, r] into one color
    # initialize with 0 for length 1 intervals
    dp = [[0] * m for _ in range(m)]

    for length in range(2, m + 1):
        for l in range(m - length + 1):
            r = l + length - 1
            if a[l] == a[r]:
                dp[l][r] = dp[l + 1][r - 1] + 1
            else:
                dp[l][r] = min(dp[l + 1][r], dp[l][r - 1]) + 1

    print(dp[0][m - 1] if m > 0 else 0)

if __name__ == "__main__":
    solve()
