import sys

MOD = 10**9 + 7

def solve():
    s = sys.stdin.readline().strip()
    n = len(s)

    # dp[state], state: 0=0, 1=1(next bomb), 2=1(prev bomb), 3=*, 4=2
    dp = [0] * 5

    if s[0] == '0':
        dp[0] = 1
    elif s[0] == '1':
        dp[2] = 1
    elif s[0] == '*':
        dp[3] = 1
    elif s[0] == '?':
        dp[0] = dp[2] = dp[3] = 1

    for i in range(1, n):
        new_dp = [0] * 5
        if s[i] == '0':
            new_dp[0] = (dp[0] + dp[2]) % MOD
        elif s[i] == '1':
            new_dp[1] = (dp[0] + dp[2]) % MOD
            new_dp[2] = dp[3]
