        new_dp = [0] * 5
        if s[i] == '0':
            new_dp[0] = (dp[0] + dp[2]) % MOD
        elif s[i] == '1':
            new_dp[1] = (dp[0] + dp[2]) % MOD
            new_dp[2] = dp[3]
        elif s[i] == '2':
            new_dp[4] = dp[3]
        elif s[i] == '*':
            new_dp[3] = (dp[1] + dp[3] + dp[4]) % MOD
        elif s[i] == '?':
            new_dp[0] = (dp[0] + dp[2]) % MOD
            new_dp[1] = (dp[0] + dp[2]) % MOD
            new_dp[2] = dp[3]
            new_dp[3] = (dp[1] + dp[3] + dp[4]) % MOD
            new_dp[4] = dp[3]
