import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    N = data[0]
    K = int(data[1])

    # DP[pos][k][tight][started]
    # pos: current digit position (0-index from most significant)
    # k: number of non-zero digits used so far
    # tight: whether we are bound by the prefix of N (1 = bound, 0 = free)
    # started: whether we have started placing non-leading-zero digits (1 = yes, 0 = no)
    dp = [[[[0 for _ in range(2)] for _ in range(2)] for _ in range(K + 2)] for _ in range(len(N) + 2)]

    dp[0][0][1][0] = 1  # at position 0, 0 non-zero digits, tight, not started

    for pos in range(len(N)):
        limit = int(N[pos])
        for k in range(K + 1):
            for tight in range(2):
                for started in range(2):
                    cur = dp[pos][k][tight][started]
                    if cur == 0:
                        continue
                    # try all possible digits at this position
                    for dig in range(0, 10):
                        if tight and dig > limit:
                            break
                        next_tight = 1 if (tight and dig == limit) else 0
                        next_started = 1 if (started or dig != 0) else 0
                        next_k = k + (1 if dig != 0 else 0)
                        if next_k > K:
                            continue
                        if next_started:
                            dp[pos + 1][next_k][next_tight][next_started] += cur
                        else:
                            # still not started, only one way (dig = 0)
                            dp[pos + 1][next_k][next_tight][next_started] += cur

    # sum results: all positions fully processed, exactly K non-zero digits, started = 1
    res = 0
    for tight in range(2):
        res += dp[len(N)][K][tight][1]
    print(res)

if __name__ == "__main__":
    solve()
