    exp_count = {}
    for p in primes:
        exp = 0
        power = p
        while power <= N:
            exp += N // power
            power *= p
        exp_count[p] = exp

    # Step 3: Count primes with exponent ≥ 2, 4, 14, 24, 74
    cnt = {2: 0, 4: 0, 14: 0, 24: 0, 74: 0}
    for e in exp_count.values():
        if e >= 2:
            cnt[2] += 1
        if e >= 4:
            cnt[4] += 1
        if e >= 14:
            cnt[14] += 1
        if e >= 24:
            cnt[24] += 1
        if e >= 74:
            cnt[74] += 1

    # Step 4: Count patterns
    total = 0

    # Pattern 1: p^74
    total += cnt[74]

    # Pattern 2: p^2 q^24, p ≠ q
    if cnt[24] > 0:
