def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    it = iter(input_data)
    n = int(next(it))
    m = int(next(it))
    a = [[int(next(it)) for _ in range(m)] for _ in range(n)]

    # We'll work with a copy to avoid modifying original while checking
    b = [row[:] for row in a]

    # First, propagate constraints from fixed positive numbers:
    # For each cell, it must be > left and > above, and < below and < right when those are fixed.
    # Since zeros are only internal, we can first set zeros to 1 as a starting point.
    for i in range(n):
        for j in range(m):
            if b[i][j] == 0:
                b[i][j] = 1

    # Now we need to enforce row and column increasing constraints.
    # We'll do a two-pass constraint propagation:
    # 1. Make sure each cell is > left and > above.
    # 2. Make sure each cell is < right and < below (where those are fixed non‑zero).
    # Because zeros are internal, we can iterate.

    # Pass 1: forward (top-left to bottom-right) to satisfy > left and > above
    for i in range(n):
        for j in range(m):
            if i > 0 and b[i][j] <= b[i-1][j]:
                needed = b[i-1][j] + 1
                # if original is fixed and larger, impossible
                if a[i][j] != 0 and a[i][j] < needed:
                    print(-1)
                    return
                if a[i][j] == 0:
                    b[i][j] = needed
                else:
                    b[i][j] = a[i][j]  # keep fixed, but we already know it's >= needed
            if j > 0 and b[i][j] <= b[i][j-1]:
                needed = b[i][j-1] + 1
                if a[i][j] != 0 and a[i][j] < needed:
                    print(-1)
                    return
                if a[i][j] == 0:
