import sys

def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    n = int(input_data[0])
    board = input_data[1:1+n]

    # We'll store positions of pieces and attacked cells
    pieces = []
    attacked = [[False]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if board[i][j] == 'o':
                pieces.append((i, j))
            elif board[i][j] == 'x':
                attacked[i][j] = True

    # We need to find a set of moves (dx, dy) such that:
    # 1. For every piece and every attacked cell, there exists a move that takes the piece to that cell.
    # 2. For every piece and every '.' cell, no move can take the piece there.

    # We can work in terms of differences between piece positions and attacked cells.
    # Let's collect all possible (dx, dy) from pieces to attacked cells.
    moves_set = set()
    for pi, pj in pieces:
        for i in range(n):
            for j in range(n):
                if attacked[i][j]:
                    dx = i - pi
                    dy = j - pj
                    moves_set.add((dx, dy))

    # Now we need to check if using these moves we don't attack any '.' cell.
    # Also we must make sure every attacked cell is reachable by at least one piece using one of these moves.
    reachable_attacked = [[False]*n for _ in range(n)]

    # For each piece, apply each move and mark reachable cells.
    for pi, pj in pieces:
        for dx, dy in moves_set:
            ni = pi + dx
            nj = pj + dy
            if 0 <= ni < n and 0 <= nj < n:
                reachable_attacked[ni][nj] = True

    # Check consistency:
    # 1. All attacked cells must be reachable.
    for i in range(n):
        for j in range(n):
            if attacked[i][j] and not reachable_attacked[i][j]:
                print("NO")
                return
    # 2. No '.' cell may be reachable.
    for i in range(n):
        for j in range(n):
            if board[i][j] == '.' and reachable_attacked[i][j]:
                print("NO")
                return

    # If we reach here, the moves_set is valid.
    # Now we need to output the moves in the required format.
    size = 2*n - 1
    result = [['.' for _ in range(size)] for __ in range(size)]
    center = n-1
    result[center][center] = 'o'
    for dx, dy in moves_set:
        x = center + dx
        y = center + dy
        if 0 <= x < size and 0 <= y < size:
            result[x][y] = 'x'

    print("YES")
    for row in result:
        print(''.join(row))

