import sys

MOD = 1_000_000_007

def solve():
    H, W, K = map(int, sys.stdin.readline().split())
    K -= 1  # 0-indexed for easier array access

    # dp[h][pos] = number of ways to reach position pos at horizontal line h
    dp = [[0] * W for _ in range(H + 1)]
    dp[0][0] = 1  # start at top-left vertical line (position 0)

    # Precompute valid connection patterns between adjacent vertical lines
    # for a given set of horizontal lines in a row (height level)
    # We represent a pattern as a bitmask of length W-1, where bit i = 1 means a horizontal line connects i and i+1
    valid_patterns = []

    # generate all bitmasks for W-1 slots
    for mask in range(1 << (W - 1)):
        valid = True
        for i in range(W - 2):
            if (mask >> i) & 1 and (mask >> (i + 1)) & 1:
                valid = False  # two adjacent horizontal lines would touch same vertical line
                break
        if valid:
            valid_patterns.append(mask)

    for h in range(H):
        for mask in valid_patterns:
            # Determine transitions: where does each vertical line move?
            # If there's a line to the left, move left; if to the right, move right; else stay.
            trans = [0] * W
            for i in range(W):
                if i > 0 and (mask >> (i - 1)) & 1:
                    trans[i] = -1  # move left
                elif i < W - 1 and (mask >> i) & 1:
                    trans[i] = 1   # move right
                else:
                    trans[i] = 0   # stay

            # Apply transition to dp
            for i in range(W):
                if dp[h][i] == 0:
                    continue
                ni = i + trans[i]
                dp[h + 1][ni] = (dp[h + 1][ni] + dp[h][i]) % MOD

    print(dp[H][K] % MOD)

if __name__ == "__main__":
    solve()
