            return total_patties[level - 1] + 1  # middle patty
        x -= 1
        if x <= total_layers[level - 1]:
            return total_patties[level - 1] + 1 + count_patties(level - 1, x)
        # x covers whole second half and top bun
        return total_patties[level - 1] * 2 + 1

    print(count_patties(N, X))

