    if k > 1 and n > 1:
        for j in range(m):
            consecutive = 0
            for i in range(n):
                if classroom[i][j] == '.':
                    consecutive += 1
                else:
                    if consecutive >= k:
                        total += consecutive - k + 1
                    consecutive = 0
            if consecutive >= k:
