def solve():
    n, k = map(int, input().split())

    # dp[comp][state]
    # state: 0=both same and equal to previous both same
    #        1=both same and different from previous both same
    #        2=top=prev top, bottom!=prev bottom
    #        3=top!=prev top, bottom=prev bottom
    dp = [[0]*4 for _ in range(k+1)]

    # first column
    dp[1][0] = 2  # BB or WW, 1 component
    dp[2][2] = 1  # BW, 2 components
    dp[2][3] = 1  # WB, 2 components

    for i in range(2, n+1):
        new_dp = [[0]*4 for _ in range(k+1)]
        for comp in range(1, min(k, 2*i) + 1):
            for st in range(4):
                val = dp[comp][st]
                if val == 0:
