import sys
import math

def divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(divs)

def main():
    n = int(sys.stdin.readline().strip())
    divs = divisors(n)
    fun_values = []
    for d in divs:
        # fun = (n^2 + 2n - n*d) / (2*d)
        numerator = n * n + 2 * n - n * d
        denominator = 2 * d
        fun = numerator // denominator
        fun_values.append(fun)
    fun_values.sort()
    print(' '.join(map(str, fun_values)))

if __name__ == "__main__":
    main()

