    if not data:
        return
    n, k = map(int, data[:2])
    ips = [ip_to_int(ip) for ip in data[2:2 + n]]

    mask = 0
    # Try bits from most significant to least
    for bit in range(31, -1, -1):
        mask |= (1 << bit)
        networks = set()
        for ip in ips:
            networks.add(ip & mask)
        if len(networks) == k:
            # Check if mask is valid (has form 1...10...0)
            # That means mask bits must be a prefix of 1's then 0's
            # So mask+1 must be a power of two (or mask == 0xFFFFFFFF)
            if mask == 0xFFFFFFFF:
                print(int_to_ip(mask))
                return
            # mask+1 should have exactly one 1 in binary (power of two)
            if ((mask + 1) & mask) == 0:
                print(int_to_ip(mask))
                return
            else:
                # This mask is not valid subnet mask (not contiguous ones)
                # We need to continue searching for a valid one with fewer ones
                pass
        elif len(networks) < k:
            # Too few networks, we cannot increase ones further
            # So we should stop and check if we already have a valid mask
            # But we haven't found one yet, so we must undo this bit and continue
            mask ^= (1 << bit)

    # After loop, check if mask is valid
    if mask == 0xFFFFFFFF:
        print(int_to_ip(mask))
        return
    if ((mask + 1) & mask) == 0 and mask != 0:
        networks = set(ip & mask for ip in ips)
        if len(networks) == k:
            print(int_to_ip(mask))
