import sys

MOD = 10**9 + 7

def solve() -> None:
    N = int(sys.stdin.readline().strip())
    # valid characters: 0=A, 1=C, 2=G, 3=T
    # dp[pos][c1][c2][c3] = number of strings ending with characters c1 c2 c3
    dp = [[[[0] * 4 for _ in range(4)] for _ in range(4)] for _ in range(N + 1)]

    # Initialization for length 3 strings
    for c1 in range(4):
        for c2 in range(4):
            for c3 in range(4):
                s = [c1, c2, c3]
                # Check for "AGC"
                if s == [0, 2, 1]:
                    continue
                # Check for "ACG"
                if s == [0, 1, 2]:
                    continue
                # Check for "GAC"
                if s == [2, 0, 1]:
                    continue
                dp[3][c1][c2][c3] = 1

    # Precompute bad patterns (strings that would be invalid after one adjacent swap)
    # Represent as (a,b,c,d) meaning a b c d is invalid in final string (for length 4 substrings)
    # Actually, we need to ensure no "AGC" appears and cannot be made by swapping adjacent.
    # The forbidden patterns are:
    # AGC, ACG, GAC  (original)
    # plus patterns that become these after one swap:
    # * AGxC -> if we swap G and x, we get AxGC, so for x=C we get ACGC which is not AGC, careful.
    # Let's follow known solution: forbidden triples after swap are:
    # AGC, ACG, GAC, AG.C (AG then any then C), A.GC (A then any then GC)
    # Actually, the rule is: the condition cannot be violated by swapping two adjacent characters once.
    # So we must forbid any string where a swap of adjacent chars creates "AGC".
    # Equivalent: forbid any string containing "AGC" as substring, and also forbid patterns:
    # AGxC -> if x is anything, swapping G and x yields AxGC. If x=C then ACGC, not AGC. Wait.
