    bit = [0] * (n + 2)

    def bit_update(idx, val):
        while idx <= n:
            bit[idx] += val
            idx += idx & -idx

    def bit_query(idx):
        s = 0
        while idx > 0:
            s += bit[idx]
            idx -= idx & -idx
        return s

    def range_sum(l, r):
        # sum in [l, r], 1-indexed, l <= r
        return bit_query(r) - bit_query(l - 1)

    regions = 1
    current = 1
    res = []
    for step in range(n):
        nxt = current + k
        if nxt > n:
            nxt -= n
        # count visited in clockwise arc from current to nxt, excluding ends
        cnt = 0
        if current < nxt:
            # arc (current, nxt)
            if nxt - current > 1:
                cnt = range_sum(current + 1, nxt - 1)
