import sys

def solve() -> None:
    # segment counts for digits 0-9
    segments = [6, 2, 5, 5, 4, 5, 6, 3, 7, 6]

    data = sys.stdin.read().strip().split()
    if not data:
        return
    a, b = map(int, data)

    total = 0
    for num in range(a, b + 1):
        n = num
        while n > 0:
            total += segments[n % 10]
            n //= 10
        # special case: if number is 0 (but here a >= 1, so not needed)
        if num == 0:
            total += segments[0]

    print(total)

if __name__ == "__main__":
    solve()

