    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    road = data[2].strip()

    # DP: dp[i] = can we reach position i (1-based)
    dp = [False] * (n + 1)
    dp[1] = True  # start position

    for i in range(1, n + 1):
        if not dp[i]:
            continue
        if road[i - 1] == '#':
            continue
        # from i we can jump to i+1 ... i+k
        for j in range(i + 1, min(i + k, n) + 1):
            if road[j - 1] == '.':
                dp[j] = True
                if j == n:
                    print("YES")
                    return

    print("NO")

if __name__ == "__main__":
