import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    pixels = list(map(int, data[2:2 + n]))

    groups = [-1] * 256
    result = []

    for p in pixels:
        if groups[p] != -1:
            result.append(groups[p])
            continue

        # find the leftmost possible group start
        start = max(0, p - k + 1)
        # try to extend left until we hit a pre-assigned color or 0
        best_start = p
        for cand in range(start, p + 1):
            # check if cand can be the start of a new group
            # group would be [cand, cand + k - 1]
            # but we must ensure we don't cross a pre-assigned boundary
            if cand > 0 and groups[cand - 1] != -1:
                # we cannot include cand-1, so group must start at cand
                # check if we can assign without conflict
                ok = True
                for color in range(cand, p + 1):
                    if groups[color] != -1:
                        ok = False
                        break
                if ok:
                    # also ensure we don't exceed k in total length
                    # we will assign up to cand + k - 1, but only up to 255
                    end = min(255, cand + k - 1)
                    # check if within k and no conflicts in the whole intended group
                    conflict = False
                    for color in range(cand, end + 1):
                        if groups[color] != -1:
                            conflict = True
                            break
                    if not conflict:
                        best_start = cand
                        break
                # else continue searching
            else:
                # no left neighbor assigned, we can start here
                # check for conflicts and length
                end = min(255, cand + k - 1)
                conflict = False
                for color in range(cand, end + 1):
                    if groups[color] != -1:
                        conflict = True
                        break
                if not conflict:
                    best_start = cand
                    break

        # assign group [best_start, best_start + k - 1] with key = best_start
        end = min(255, best_start + k - 1)
        for color in range(best_start, end + 1):
            groups[color] = best_start

        result.append(groups[p])

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
