import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    T = int(next(it))
    out_lines = []
    for _ in range(T):
        n = int(next(it))
        p_prev = -1
        c_prev = -1
        ok = True
        for i in range(n):
            p = int(next(it))
            c = int(next(it))
            if not ok:
                continue
            # basic checks: non-decreasing plays and clears, and clears <= plays
            if p < p_prev or c < c_prev or c > p:
                ok = False
            else:
                # clears increase cannot exceed plays increase
                if c - c_prev > p - p_prev:
                    ok = False
            p_prev, c_prev = p, c
        out_lines.append("YES" if ok else "NO")
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

