import sys

class TrieNode:
    __slots__ = ('children', 'count')
    def __init__(self):
        self.children = [None, None]
        self.count = 0

class Trie:
    def __init__(self, bits=31):
        self.root = TrieNode()
        self.bits = bits   # we consider numbers up to 2^bits (here bits=30 since 10^9 < 2^30)

    def insert(self, x):
        node = self.root
        for i in range(self.bits - 1, -1, -1):
            bit = (x >> i) & 1
            if node.children[bit] is None:
                node.children[bit] = TrieNode()
            node = node.children[bit]
            node.count += 1

    def erase(self, x):
        node = self.root
        for i in range(self.bits - 1, -1, -1):
            bit = (x >> i) & 1
            node = node.children[bit]
            node.count -= 1

    def max_xor(self, x):
        node = self.root
        res = 0
        for i in range(self.bits - 1, -1, -1):
            bit = (x >> i) & 1
            # we want opposite bit if it exists and has count > 0
            toggled = 1 - bit
            if node.children[toggled] and node.children[toggled].count > 0:
                res |= (1 << i)
                node = node.children[toggled]
            else:
                node = node.children[bit]
        return res

def main():
    q = int(sys.stdin.readline())
    trie = Trie(bits=31)  # 31 bits to cover 0..10^9 (30 bits enough but 31 is safe)
    # Initially multiset contains 0
    trie.insert(0)

    out_lines = []
    for _ in range(q):
        op, val = sys.stdin.readline().split()
        x = int(val)
        if op == '+':
            trie.insert(x)
        elif op == '-':
            trie.erase(x)
        else:  # '?'
            out_lines.append(str(trie.max_xor(x)))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    main()
