import sys
sys.setrecursionlimit(10**6)

def solve():
    data = sys.stdin.read().strip().split()
    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1
    k = int(data[idx]); idx += 1

    grid = []
    for _ in range(n):
        grid.append(list(data[idx])); idx += 1

    queries = []
    for _ in range(k):
        x = int(data[idx]) - 1; idx += 1
        y = int(data[idx]) - 1; idx += 1
        queries.append((x, y))

    visited = [[-1] * m for _ in range(n)]
    component_pictures = []
    moves = [(1,0), (-1,0), (0,1), (0,-1)]

    def dfs(r, c, comp_id):
        stack = [(r, c)]
        visited[r][c] = comp_id
        pictures = 0
        while stack:
            cr, cc = stack.pop()
            for dr, dc in moves:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if grid[nr][nc] == '*':
                        pictures += 1
                    else:
                        if visited[nr][nc] == -1:
                            visited[nr][nc] = comp_id
                            stack.append((nr, nc))
        return pictures

    comp_id = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and visited[i][j] == -1:
                pics = dfs(i, j, comp_id)
                component_pictures.append(pics)
                comp_id += 1

    out_lines = []
    for x, y in queries:
        comp = visited[x][y]
        out_lines.append(str(component_pictures[comp]))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

