import math
from collections import defaultdict

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    arr = list(map(int, data[2:2 + n]))

    # Precompute prime powers for factor normalization
    max_val = 10**5
    factor = [i for i in range(max_val + 1)]
    for i in range(2, int(max_val**0.5) + 1):
        if factor[i] == i:
            for j in range(i * i, max_val + 1, i):
                if factor[j] == j:
                    factor[j] = i

    def normalize(x):
        # Factorize x and remove k-th powers from its prime factorization
        res = 1
        while x > 1:
            p = factor[x]
            cnt = 0
            while x % p == 0:
                cnt += 1
                x //= p
            cnt %= k
            if cnt > 0:
                res *= p ** cnt
        return res

    def complement(y):
        # Find the minimal number z such that y * z is a perfect k-th power
        need = 1
        temp = y
        while temp > 1:
            p = factor[temp]
            cnt = 0
            while temp % p == 0:
                cnt += 1
                temp //= p
            rem = (k - cnt) % k
            if rem > 0:
                need *= p ** rem
        # Check if need can be too large ( > max(a_i) ), if so skip
        if need > 10**5:
            return -1
        return need

    freq = defaultdict(int)
    ans = 0

    for a in arr:
        norm = normalize(a)
        comp = complement(norm)
        if comp != -1:
            ans += freq[comp]
        freq[norm] += 1

    print(ans)

if __name__ == "__main__":
    main()

