import sys
import math

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, k = map(int, data[:2])
    arr = list(map(int, data[2:2+n]))

    # Precompute the maximum value to limit prime factorization range
    max_val = 10**5
    # Prime sieve up to sqrt(max_val) is enough for factorization
    limit = int(math.sqrt(max_val)) + 2
    is_prime = [True] * (limit + 1)
    primes = []
    for i in range(2, limit + 1):
        if is_prime[i]:
            primes.append(i)
            for j in range(i*i, limit + 1, i):
                is_prime[j] = False

    def factorize(x):
        res = {}
        num = x
        for p in primes:
            if p * p > num:
                break
            cnt = 0
            while num % p == 0:
                cnt += 1
                num //= p
            if cnt % k != 0:
                res[p] = cnt % k
        if num > 1:
            if 1 % k != 0:  # always true for k >= 2
                res[num] = 1 % k
        return res

    def complement_factor(fact):
        comp = {}
        for p, exp in fact.items():
            needed = (k - exp) % k
            if needed != 0:
                comp[p] = needed
        return comp

    from collections import defaultdict

    freq = defaultdict(int)
    pairs = 0

    for val in arr:
        fact = factorize(val)
        comp = complement_factor(fact)
        # Convert to tuple for hashing
        comp_key = tuple(sorted(comp.items()))
        pairs += freq[comp_key]

        # Store the original factorization
        orig_key = tuple(sorted(fact.items()))
        freq[orig_key] += 1

    print(pairs)

if __name__ == "__main__":
