import sys
import math

def sieve(limit):
    """Return list of primes up to limit using sieve of Eratosthenes."""
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    primes = []
    for i in range(2, limit + 1):
        if is_prime[i]:
            primes.append(i)
            for j in range(i * i, limit + 1, i):
                is_prime[j] = False
    return primes

def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    n = int(input_data[0])
    a = list(map(int, input_data[1:1 + n]))

    # Generate enough primes (we need at most n primes, but we'll generate a safe amount)
    # Since a_i <= 10^5 and n <= 10^5, 2*n primes is more than enough.
    primes = sieve(200000)  # enough primes

    b = [0] * n
    used = set()

    # First, copy a to b and check pairwise coprimality as we go
    for i in range(n):
        if i == 0:
            b[i] = a[i]
            used.add(b[i])
            continue

        # Check if we can keep a[i] while maintaining pairwise coprimality
        candidate = a[i]
        conflict = False
        for prev in b[:i]:
            if math.gcd(prev, candidate) != 1:
                conflict = True
                break

        if not conflict:
            b[i] = candidate
            used.add(candidate)
        else:
            # Need to find the smallest number >= a[i] that is coprime with all previous
            # and not used before (to avoid duplicates, though duplicates are okay if coprime)
            # Actually duplicates are allowed if coprime? No, duplicate numbers share the same value, gcd(x,x)=x>1 unless x=1.
            # Since b_i >=2, duplicate numbers would have gcd>1, so we must avoid duplicates.
            found = False
            while True:
                ok = True
                for prev in b[:i]:
                    if math.gcd(prev, candidate) != 1:
                        ok = False
                        break
                if ok and candidate not in used:
                    b[i] = candidate
                    used.add(candidate)
                    found = True
                    break
                candidate += 1
                if candidate > 200000:  # safety bound
                    break
            if not found:
                # Fallback: use primes that are not used
                for p in primes:
                    if p not in used:
                        ok = True
                        for prev in b[:i]:
                            if math.gcd(prev, p) != 1:
                                ok = False
                                break
                        if ok:
                            b[i] = p
                            used.add(p)
                            break

    print(' '.join(map(str, b)))

if __name__ == "__main__":
    solve()

