import sys

def compare(s1: str, s2: str) -> int:
    # Custom comparator: s1 + s2 vs s2 + s1
    return (s1 + s2) > (s2 + s1)

def merge_sort(arr):
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])
    return merge(left, right)

