import sys

def normalize(s):
    # Remove leading zeros, but keep a single zero if the whole string is zeros
    i = 0
    n = len(s)
    while i < n and s[i] == '0':
        i += 1
    if i == n:
        return '0'
    return s[i:]

def compare_golden(a, b):
    a = normalize(a)
    b = normalize(b)

    # Quick length‑based comparison (because q > 1)
    if len(a) != len(b):
        return '>' if len(a) > len(b) else '<'

    # Same length: lexicographic comparison works because q > 1 and digits are 0/1
    if a > b:
        return '>'
    elif a < b:
        return '<'
    else:
        return '='

