import math

MOD = 10**9 + 7

def phi(x):
    # Euler's totient for one value, using factorization
    result = x
    p = 2
    while p * p <= x:
        if x % p == 0:
            while x % p == 0:
                x //= p
            result -= result // p
        p += 1 if p == 2 else 2  # check 2, then odd numbers
    if x > 1:
        result -= result // x
    return result

def solve():
    n, k = map(int, sys.stdin.readline().split())
    if n == 1:
        print(1)
        return
    # Effective iterations
    m = (k + 1) // 2  # ceil(k/2)
    val = n
    for _ in range(m):
        val = phi(val)
        if val == 1:
            break
    print(val % MOD)

if __name__ == "__main__":
    solve()

