def solve():
    n = int(sys.stdin.readline().strip())
    if n == 1:
        print(1)
        return

    # Find smallest prime divisor
    def smallest_prime_divisor(x):
        if x % 2 == 0:
            return 2
        for i in range(3, int(math.isqrt(x)) + 1, 2):
            if x % i == 0:
                return i
        return x  # x is prime

    p = smallest_prime_divisor(n)
    # Check if n is power of p
    m = n
    while m % p == 0:
        m //= p
    if m == 1:
        print(p)
    else:
        print(1)

if __name__ == "__main__":
    solve()

