We can think of this as a maximum flow problem.  

The frog moves from leaf to leaf if they share the same row or column.  
We want to remove the minimum number of leaves (excluding S and T) to disconnect S from T in this movement graph.  

This is a minimum cut problem.  

We can model it as:  
- Each leaf is a node.  
- If a leaf is in the same row or column as another leaf, there’s an edge between them (bidirectional, infinite capacity? Wait — but here, removing a leaf removes all edges from it, so we need to model leaf removal as node capacity, not edge capacity).  

A standard trick: split each leaf node into an “in” node and an “out” node, connected by an edge of capacity 1 (so cutting it means removing that leaf). For S and T, we give infinite capacity so they can’t be removed.  

Then, for movement (same row/column), we connect “out” of one leaf to “in” of the other leaf with infinite capacity (so the only way to cut movement is to remove leaf nodes).  

But since movement is allowed both ways, we add edges both ways.  

Then, compute min-cut from S_out to T_in.  

---

Here’s the implementation:

```python
from collections import deque
import sys

INF = 10**9

class MaxFlow:
    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        forward = [to, cap, None]
        backward = [fr, 0, forward]
        forward[2] = backward
        self.adj[fr].append(forward)
        self.adj[to].append(backward)

    def bfs_level(self, s, t):
        level = [-1] * self.n
        q = deque([s])
        level[s] = 0
        while q:
            v = q.popleft()
            for to, cap, rev in self.adj[v]:
                if cap > 0 and level[to] < 0:
                    level[to] = level[v] + 1
                    q.append(to)
        return level

    def dfs(self, v, t, f, level, it):
        if v == t:
            return f
        for i in range(it[v], len(self.adj[v])):
            it[v] = i
            to, cap, rev = self.adj[v][i]
            if cap > 0 and level[v] < level[to]:
                ret = self.dfs(to, t, min(f, cap), level, it)
                if ret > 0:
                    self.adj[v][i][1] -= ret
                    rev[1] += ret
                    return ret
        return 0

    def max_flow(self, s, t):
        flow = 0
        while True:
            level = self.bfs_level(s, t)
            if level[t] < 0:
                break
            it = [0] * self.n
            while True:
                f = self.dfs(s, t, INF, level, it)
                if f == 0:
                    break
                flow += f
        return flow

def main():
    input = sys.stdin.read().split()
    H, W = map(int, input[:2])
    grid = input[2:]

    leaves = []
    leaf_id = {}
    sid = tid = -1
    for i in range(H):
        for j in range(W):
            if grid[i][j] in 'oSST':
                leaf_id[(i, j)] = len(leaves)
                leaves.append((i, j))
                if grid[i][j] == 'S':
                    sid = len(leaves) - 1
                elif grid[i][j] == 'T':
                    tid = len(leaves) - 1

    if sid == -1 or tid == -1:
        print(-1)
        return

    # Same row/col check
    # Graph: each leaf => in_node = idx*2, out_node = idx*2+1
    n_leaves = len(leaves)
    mf = MaxFlow(2 * n_leaves)

    # Connect in to out with capacity 1 (for normal leaves), INF for S/T
    for idx, (r, c) in enumerate(leaves):
        if idx == sid or idx == tid:
            mf.add_edge(2*idx, 2*idx+1, INF)
        else:
            mf.add_edge(2*idx, 2*idx+1, 1)

    # Rows and cols connections
    # Connect out_node of leaf A to in_node of leaf B if same row/col
    # But careful: if A and B same row, they can jump both ways.
    # So we connect both directions out->in with INF capacity.

    # Group by rows
    row_leaf = [[] for _ in range(H)]
    col_leaf = [[] for _ in range(W)]
    for idx, (r, c) in enumerate(leaves):
        row_leaf[r].append(idx)
        col_leaf[c].append(idx)

    for r in range(H):
        for a in row_leaf[r]:
            for b in row_leaf[r]:
                if a != b:
                    mf.add_edge(2*a+1, 2*b, INF)
    for c in range(W):
        for a in col_leaf[c]:
            for b in col_leaf[c]:
                if a != b:
                    mf.add_edge(2*a+1, 2*b, INF)

    # Min cut from S_out to T_in? Wait, we want to disconnect S from T.
    # Source = S_out (2*sid+1), Sink = T_in (2*tid)
    # But careful: S_in(2*sid) -> S_out(2*sid+1) is INF, so source could be S_in.
    # Actually, we can start at S_out because frog starts at S leaf and can move out.
    # But in flow, we want to cut paths from S to T, so source = S_out, sink = T_in.

    source = 2*sid+1
    sink = 2*tid
    flow = mf.max_flow(source, sink)

    if flow >= INF//2:
        print(-1)
    else:
        print(flow)

if __name__ == "__main__":
    main()
