import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1 + n]))  # cards in hand
    b = list(map(int, data[1 + n:1 + 2 * n]))  # cards in pile (top to bottom)

    # Find position of card 1 in pile
    pos1_in_pile = -1
    for i in range(n):
        if b[i] == 1:
            pos1_in_pile = i
            break

    # Check if we can finish without extra cycles (starting with 1 already in correct order)
    can_win_directly = True
    if pos1_in_pile != -1:
        # verify that from position of 1 onwards, cards are consecutive increasing
        for k in range(pos1_in_pile + 1, n):
            if b[k] != b[k - 1] + 1:
                can_win_directly = False
                break
        if can_win_directly:
            # the cards before pos1_in_pile must be playable with empty/new cards
            needed = b[pos1_in_pile] - 1  # how many cards after 1 we already have in order
            for i in range(pos1_in_pile):
                if b[i] != 0 and b[i] <= needed + i + 1:
                    can_win_directly = False
                    break
            if can_win_directly:
                print(pos1_in_pile)
                return

    # General case: simulate
    # First, find positions of each card in pile
    pile_pos = [0] * (n + 1)
    for i in range(n):
        if b[i] != 0:
            pile_pos[b[i]] = i + 1  # 1-indexed for easier calculations

    # For each card x, we need to play until we can place it
    # We want max over all x of (pile_pos[x] - x + 1 + n)
    max_needed = 0
    for x in range(1, n + 1):
        if pile_pos[x] > 0:
            # card x is in pile at position pile_pos[x]
            # we need pile_pos[x] - (x-1) moves to bring it to top after x-1 is placed
            moves_for_x = pile_pos[x] - (x - 1)
            if moves_for_x > max_needed:
                max_needed = moves_for_x

    # Additional requirement: we might need extra empty draws
    # We'll compute answer as max_needed + n
    answer = max_needed + n
    print(answer)

if __name__ == "__main__":
