    ans = 0
    for hour in range(n):
        if hour >= 7 ** len_n:
            break
        for minute in range(m):
            if minute >= 7 ** len_m:
                break
            if can_use_digits(hour, minute, len_n, len_m):
                ans += 1
    print(ans)

if __name__ == "__main__":
