def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    s = data[1]

    # Count total opening and closing brackets
    open_count = s.count('(')
    close_count = n - open_count

    # If counts don't match, impossible
    if open_count != close_count:
        print(-1)
        return

    balance = 0
    min_balance = 0
    # First pass to find minimal balance
    for ch in s:
        if ch == '(':
            balance += 1
        else:
            balance -= 1
        if balance < min_balance:
            min_balance = balance

    # Reset for second pass to count segments
    balance = 0
    total_time = 0
    segment_start = -1

    for i, ch in enumerate(s):
        if ch == '(':
            balance += 1
        else:
            balance -= 1

        # If balance drops below 0, start a problematic segment
        if balance < 0 and segment_start == -1:
            segment_start = i

        # If balance returns to 0 after being negative, end the segment
        if balance == 0 and segment_start != -1:
            total_time += (i - segment_start + 1)
            segment_start = -1

    print(total_time)

if __name__ == "__main__":
    solve()

