import sys

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n = int(data[0])
    revealed = data[1]
    m = int(data[2])
    words = data[3:3 + m]

    # Set of already revealed letters (excluding '*')
    known_letters = set(ch for ch in revealed if ch != '*')

    # Filter possible hidden words that match the revealed pattern
    possible = []
    for w in words:
        ok = True
        for i in range(n):
            if revealed[i] != '*':
                if w[i] != revealed[i]:
                    ok = False
                    break
            else:
                # Hidden position must not be already revealed letter
                if w[i] in known_letters:
                    ok = False
                    break
        if ok:
            possible.append(w)

    # We need letters that could be guessed now (not already revealed)
    # and that are present in *all* possible words, but not in the same position?
    # Wait, reading problem carefully:
    # Polycarpus wants to tell a letter such that the host will assuredly reveal at least one more letter.
    # That means: the letter must be present in the hidden word in at least one *still hidden* position,
    # and for every possible word consistent with current knowledge, that letter must appear in at least
    # one hidden position. If for some possible word the letter doesn't appear in any hidden position,
    # then it's not guaranteed the host will reveal anything.

    hidden_positions = [i for i in range(n) if revealed[i] == '*']
    if not hidden_positions:
        print(0)
        return

    candidates = set()
    # Check each lowercase letter
    for ch in 'abcdefghijklmnopqrstuvwxyz':
        if ch in known_letters:
            continue  # already revealed, can't guess again
        ok_for_all = True
        for w in possible:
            # Does ch appear in any hidden position in w?
            found = False
            for idx in hidden_positions:
                if w[idx] == ch:
                    found = True
                    break
            if not found:
                ok_for_all = False
                break
        if ok_for_all:
            candidates.add(ch)

    print(len(candidates))

if __name__ == "__main__":
    solve()

