import sys

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n, a, b, k, f = map(int, data[0].split())
    trips = [line.split() for line in data[1:]]

    # Step 1: compute cost of each trip based on transshipment
    cost_per_trip = []
    prev_dest = None
    for start, end in trips:
        if start == prev_dest:
            cost_per_trip.append(b)
        else:
            cost_per_trip.append(a)
        prev_dest = end

    # Step 2: aggregate total cost per unordered route
    route_cost = {}
    for i, (start, end) in enumerate(trips):
        key = tuple(sorted((start, end)))
        route_cost[key] = route_cost.get(key, 0) + cost_per_trip[i]

    # Step 3: find routes with highest total cost to consider for travel cards
    sorted_routes = sorted(route_cost.values(), reverse=True)

    # Step 4: apply up to k travel cards if beneficial
    total_cost = sum(cost_per_trip)
    for i in range(min(k, len(sorted_routes))):
        if sorted_routes[i] > f:
            total_cost -= sorted_routes[i] - f  # replace cost with card cost
        else:
            break

    print(total_cost)

