def lis_length(seq):
    # O(N^2) LIS DP
    if not seq:
        return 0
    dp = [1] * len(seq)
    for i in range(len(seq)):
        for j in range(i):
            if seq[j] < seq[i]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

def solve():
    import sys
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    A = list(map(int, data[1:1+N]))

    total = 0
    count = 0

    # Recursively generate all X
    X = [0] * N
    def gen(pos):
        nonlocal total, count
        if pos == N:
            total += lis_length(X)
            count += 1
            return
        for val in range(1, A[pos] + 1):
            X[pos] = val
            gen(pos + 1)

    gen(0)
    # Expected value = total / count
    # Output total * inv(count) mod MOD
    inv_count = modinv(count)
    result = (total % MOD) * inv_count % MOD
    print(result)

