def solve():
    import sys
    input = sys.stdin.read
    N, K = map(int, input().split())

    if N == 1:
        print(1)
        return

    # DP array: ways[l][r] for 1 <= l <= r <= N
    ways = [[0]*(N+2) for _ in range(N+2)]

    # Fill DP in increasing order of interval length
    for length in range(1, N+1):
        for l in range(1, N-length+2):
            r = l + length - 1
            step = K - N + (r - l + 1)
            if step < 1:
                ways[l][r] = 0
                continue
            if l == 1 and r == 1:
                ways[l][r] = 1 if step == 1 else 0
            elif l == 1:
                if step == 1:
                    ways[l][r] = 1
                else:
                    ways[l][r] = ways[l][r-1]
            elif r == 1:
                if step == 1:
                    ways[l][r] = 1
                else:
                    ways[l][r] = ways[l+1][r]
            else:
                ways[l][r] = (ways[l+1][r] + ways[l][r-1]) % MOD

    removal_ways = ways[1][N] % MOD

    # Insertion ways = 2^(N-1) % MOD
    insertion_ways = pow(2, N-1, MOD)

    ans = (removal_ways * insertion_ways) % MOD
    print(ans)

if __name__ == "__main__":
    solve()

