def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1 + n]))

    # Simulate the process
    stacks = a[:]
    output = []

    while stacks:
        # Check for sliding before choosing the tallest
        changed = True
        while changed:
            changed = False
            for i in range(len(stacks) - 1):
                if abs(stacks[i] - stacks[i + 1]) >= 2:
                    # taller stack loses one ravioli to the shorter stack
                    if stacks[i] > stacks[i + 1]:
                        stacks[i] -= 1
                        stacks[i + 1] += 1
                    else:
                        stacks[i] += 1
                        stacks[i + 1] -= 1
                    changed = True
                    # Only one change per outer pass, then recheck
                    break

        # Find tallest (leftmost if tie)
        max_idx = 0
        for i in range(1, len(stacks)):
            if stacks[i] > stacks[max_idx]:
                max_idx = i
        # Remove it and add to output
        output.append(stacks.pop(max_idx))

    # Check if output is non-decreasing
    for i in range(1, len(output)):
        if output[i] < output[i - 1]:
            print("NO")
            return
    print("YES")

if __name__ == "__main__":
    solve()

