def solve():
    data = sys.stdin.read().strip().split()
    t = int(data[0])
    out = []
    idx = 1
    for _ in range(t):
        n = int(data[idx]); m = int(data[idx + 1])
        idx += 2
        if n == 1:
            out.append("0")
        elif n == 2:
            out.append(str(m))
        else:
            # For n >= 3, best is to put all m into two ends alternatively
            # Maximum sum of differences = 2 * m
            out.append(str(min(2 * m, 2 * m)))  # Actually it's exactly 2*m for n >= 3
    sys.stdout.write("\n".join(out))

