import sys

def solve():
    s = sys.stdin.readline().strip()

    # Condition 1: length at least 4
    if len(s) < 4:
        print("WA")
        return

    # Condition 2: first character must be 'A'
    if s[0] != 'A':
        print("WA")
        return

    # Condition 3: exactly one 'C' between positions 2 and len(s)-2 (inclusive)
    # positions are zero-indexed: 2 -> third char, len(s)-2 -> second last char
    c_count = 0
    for i in range(2, len(s) - 1):
        if s[i] == 'C':
            c_count += 1

    if c_count != 1:
        print("WA")
        return

    # Condition 4: all other letters must be lowercase
    # We already know s[0] is 'A', and there is exactly one 'C' in the allowed range.
    # Check all characters except the first and the 'C' position(s)
    for i, ch in enumerate(s):
        if i == 0:
            continue
        if ch == 'C' and 2 <= i <= len(s) - 2:
            continue
        if not ch.islower():
            print("WA")
            return

    print("AC")

