import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    testimonies = [[] for _ in range(N)]

    for i in range(N):
        Ai = int(next(it))
        for _ in range(Ai):
            x = int(next(it)) - 1  # convert to 0-index
            y = int(next(it))
            testimonies[i].append((x, y))

    ans = 0
    # brute force over all 2^N possibilities
    for mask in range(1 << N):
        ok = True
        for i in range(N):
            if not (mask >> i & 1):  # person i is unkind, skip checking testimonies
                continue
            # person i is honest, check all testimonies
            for x, y in testimonies[i]:
                expected = (mask >> x) & 1
                if expected != y:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            # count honest persons in this valid mask
            cnt = bin(mask).count("1")
            if cnt > ans:
                ans = cnt
    print(ans)

if __name__ == "__main__":
    solve()
