import sys

def main():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    H, W = map(int, data[0].split())
    grid = list(data[1:1+H])

    # Identify rows that are not all white
    keep_rows = []
    for row in grid:
        if '#' in row:
            keep_rows.append(row)

    # Identify columns that are not all white
    # Transpose the kept rows for easier column checking
    if not keep_rows:
        return
    cols_to_keep = []
    for c in range(W):
        col_has_black = any(keep_rows[r][c] == '#' for r in range(len(keep_rows)))
        if col_has_black:
            cols_to_keep.append(c)

    # Build the result grid
    result = []
    for row in keep_rows:
        new_row = ''.join(row[c] for c in cols_to_keep)
        result.append(new_row)

    sys.stdout.write('\n'.join(result))

if __name__ == "__main__":
    main()

