import sys

def main() -> None:
    A, B, C = map(int, sys.stdin.read().split())
    # The possible sums are:
    #   Use the largest two digits to form a two‑digit number, plus the remaining digit.
    #   But we must check both orders for the two‑digit number.
    # Since A, B, C are distinct digits, we can try all permutations of which digit is used for tens place.
    digits = [A, B, C]
    best = 0
    for i in range(3):
        for j in range(3):
            if i == j:
                continue
            k = 3 - i - j  # the remaining index
            value = (digits[i] * 10 + digits[j]) + digits[k]
            if value > best:
                best = value
    print(best)

if __name__ == "__main__":
    main()

