import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    t = int(data[0])
    idx = 1
    for _ in range(t):
        n = int(data[idx]); idx += 1
        m = int(data[idx]); idx += 1
        a = list(map(int, data[idx:idx + n])); idx += n
        p = list(map(int, data[idx:idx + m])); idx += m

        # Convert positions to 0‑based and mark swapable adjacent pairs
        swapable = [False] * (n - 1)
        for pos in p:
            swapable[pos - 1] = True

        # Bubble‑sort with allowed swaps only
        # We can repeatedly sweep through the array and apply allowed swaps where needed
        # Since n ≤ 100, O(n²) is fine.
        for i in range(n):
            for j in range(n - 1):
                if a[j] > a[j + 1]:
                    if swapable[j]:
                        a[j], a[j + 1] = a[j + 1], a[j]
                    else:
                        break  # this swap not allowed, will cause failure later
            else:
                continue  # inner loop finished without breaking
            break  # outer loop break if inner broke

        # Check if sorted
        sorted_ok = all(a[i] <= a[i + 1] for i in range(n - 1))
        print("YES" if sorted_ok else "NO")

if __name__ == "__main__":
    solve()

