import sys

sys.setrecursionlimit(300000)

class DSU:
    def __init__(self, n):
        self.p = list(range(n))
        self.r = [0] * n

    def find(self, x):
        while self.p[x] != x:
            self.p[x] = self.p[self.p[x]]
            x = self.p[x]
        return x

    def union(self, a, b):
        a = self.find(a)
        b = self.find(b)
        if a == b:
            return False
        if self.r[a] < self.r[b]:
            a, b = b, a
        self.p[b] = a
        if self.r[a] == self.r[b]:
            self.r[a] += 1
        return True

def solve():
    input = sys.stdin.read().strip().split()
    if not input:
        return
    it = iter(input)
    n = int(next(it))
    m = int(next(it))
    edges = []
    for _ in range(m):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        w = int(next(it))
        edges.append((w, u, v, _))

    edges.sort(key=lambda x: x[0])

    dsu = DSU(n)
    i = 0
    ans = 0
    while i < m:
        j = i
        while j < m and edges[j][0] == edges[i][0]:
            j += 1
        # count how many edges in this weight group connect different components
        cnt = 0
        for k in range(i, j):
            w, u, v, idx = edges[k]
            if dsu.find(u) != dsu.find(v):
                cnt += 1
        # union them
        for k in range(i, j):
            w, u, v, idx = edges[k]
            if dsu.union(u, v):
                cnt -= 1
        # edges that could not be added because they'd form a cycle within the same weight group
        ans += cnt
        i = j

    print(ans)

if __name__ == "__main__":
    solve()

