import sys

def solve():
    input_data = sys.stdin.read().split()
    q = int(input_data[0])
    idx = 1
    MAX_A = 200000
    results = []

    for _ in range(q):
        n = int(input_data[idx]); idx += 1
        arr = list(map(int, input_data[idx:idx + n])); idx += n

        freq = [0] * (MAX_A + 1)
        for v in arr:
            freq[v] = 1

        # We'll try combinations of up to 3 elements
        best = 0

        # Sort unique values in descending order for early exit
        unique_vals = [v for v in range(MAX_A, 0, -1) if freq[v]]

        # Single element
        for x in unique_vals:
            best = max(best, x)

        # Two elements
        for x in unique_vals:
            for y in unique_vals:
                if x == y:
                    continue
                if x % y != 0:
                    best = max(best, x + y)
                    break  # because we go from large to small, first valid y gives max x+y

        # Three elements
        for x in unique_vals:
            for y in unique_vals:
                if x == y or x % y == 0:
                    continue
                for z in unique_vals:
                    if z == y or z == x:
                        continue
                    if x % z != 0 and y % z != 0:
                        best = max(best, x + y + z)
                        break  # first valid z is enough

        results.append(str(best))

    sys.stdout.write("\n".join(results))

