from sys import stdin
from collections import deque

def solve():
    n = int(stdin.readline())
    arr = list(map(int, stdin.readline().split()))

    # Adjust to 0-based indexing
    adj = [[] for _ in range(n)]
    # Build reverse graph
    for i in range(n):
        val = arr[i]
        if i + val < n:
            adj[i + val].append(i)
        if i - val >= 0:
            adj[i - val].append(i)

    # Answers
    res = [-1] * n

    # BFS from all even-valued nodes
    dist = [-1] * n
    q = deque()
    for i in range(n):
        if arr[i] % 2 == 0:
            dist[i] = 0
            q.append(i)

    while q:
        v = q.popleft()
        for to in adj[v]:
            if dist[to] == -1:
                dist[to] = dist[v] + 1
                q.append(to)

    for i in range(n):
        if arr[i] % 2 == 1:  # odd wants even
            res[i] = dist[i]

    # BFS from all odd-valued nodes
    dist = [-1] * n
    q = deque()
    for i in range(n):
        if arr[i] % 2 == 1:
            dist[i] = 0
            q.append(i)

    while q:
        v = q.popleft()
        for to in adj[v]:
            if dist[to] == -1:
                dist[to] = dist[v] + 1
                q.append(to)

    for i in range(n):
        if arr[i] % 2 == 0:  # even wants odd
            res[i] = dist[i]

    print(' '.join(map(str, res)))

if __name__ == "__main__":
    solve()

