import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    arr = list(map(int, data[1:1 + n]))

    count_4 = 0
    count_2_but_not_4 = 0
    count_odd = 0

    for val in arr:
        if val % 4 == 0:
            count_4 += 1
        elif val % 2 == 0:
            count_2_but_not_4 += 1
        else:
            count_odd += 1

    # Group the even numbers that are not multiples of 4 together in the permutation
    # so they don't interfere with the 4-multiple condition.
    # If we have k numbers not divisible by 2, each must be adjacent to a multiple of 4,
    # except possibly when they are at the ends and next to a multiple-of-4 or a 2-but-not-4 neighbor.
    # A known condition: count_4 >= count_odd or (count_2_but_not_4 == 0 and count_4 >= count_odd - 1)
    if count_2_but_not_4 == 0:
        if count_4 >= count_odd - 1:
            print("Yes")
        else:
            print("No")
    else:
        # The 2-but-not-4 numbers can be placed consecutively, so they act as a single block
        # for adjacency purposes. This block needs to be surrounded by multiples of 4.
        # Effectively, treat them as reducing the number of positions where odds must be separated.
        # Equivalent to: count_4 >= count_odd
        if count_4 >= count_odd:
            print("Yes")
        else:
            print("No")

if __name__ == "__main__":
    solve()
