from sys import stdin
from collections import deque

def solve():
    n = int(stdin.readline())
    arr = list(map(int, stdin.readline().split()))

    # Convert to 0-indexed
    a = [x for x in arr]

    # reversed graph: rev[i] = list of nodes v such that v can jump to i in original graph
    rev = [[] for _ in range(n)]

    for v in range(n):
        jump = a[v]
        # v -> v + jump
        if v + jump < n:
            rev[v + jump].append(v)
        # v -> v - jump
        if v - jump >= 0:
            rev[v - jump].append(v)

    # BFS from all even nodes
    # even nodes: a[i] % 2 == 0
    dist_even = [-1] * n
    q = deque()
    for i in range(n):
        if a[i] % 2 == 0:
            dist_even[i] = 0
            q.append(i)

    while q:
        u = q.popleft()
        for v in rev[u]:
            if dist_even[v] == -1:
                dist_even[v] = dist_even[u] + 1
                q.append(v)

    # BFS from all odd nodes
    dist_odd = [-1] * n
    q = deque()
    for i in range(n):
        if a[i] % 2 == 1:
            dist_odd[i] = 0
            q.append(i)

    while q:
        u = q.popleft()
        for v in rev[u]:
            if dist_odd[v] == -1:
                dist_odd[v] = dist_odd[u] + 1
                q.append(v)

    # Answer
    res = []
    for i in range(n):
        if a[i] % 2 == 0:
            # want odd parity target
            res.append(dist_odd[i])
        else:
            # want even parity target
            res.append(dist_even[i])

    print(' '.join(map(str, res)))

if __name__ == "__main__":
    solve()

