def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    c, d = map(int, data[0:2])
    n, m = map(int, data[2:4])
    k = int(data[4])

    needed = n * m - k
    if needed <= 0:
        print(0)
        return

    # dp[i] = minimal problems to get exactly i participants
    INF = 10**9
    max_needed = needed + max(n, 1)  # a bit more for safety
    dp = [INF] * (max_needed + 1)
    dp[0] = 0

    # Main round: gives n participants, costs c problems
    for i in range(max_needed + 1):
        if dp[i] != INF:
            nxt = i + n
            if nxt <= max_needed:
                dp[nxt] = min(dp[nxt], dp[i] + c)

    # Additional round: gives 1 participant, costs d problems
    for i in range(max_needed + 1):
        if dp[i] != INF:
            nxt = i + 1
            if nxt <= max_needed:
                dp[nxt] = min(dp[nxt], dp[i] + d)

    # Find minimal in dp[needed..max_needed]
    ans = INF
    for i in range(needed, max_needed + 1):
        ans = min(ans, dp[i])

    print(ans)

if __name__ == "__main__":
    solve()

