def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, m, k = map(int, data)

    # dp[i][j] = ways to paint first i bricks with j bricks different from left neighbor
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[1][0] = m  # first brick can be any of m colors

    for i in range(2, n + 1):
        for j in range(k + 1):
            # same color as previous brick -> no new difference
            dp[i][j] = dp[i - 1][j]
            # different color from previous brick -> new difference
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1] * (m - 1)) % MOD

    print(dp[n][k] % MOD)

if __name__ == "__main__":
    solve()

