import sys

def can_return_to_zero(n, angles):
    # We can think of each rotation as either +angle or -angle.
    # The goal is to check if we can sum them to 0 modulo 360.
    # Since n <= 15, we can brute-force all 2^n possibilities.

    # We'll use an iterative approach with bitmasking.
    total_combinations = 1 << n  # 2^n
    for mask in range(total_combinations):
        total = 0
        for i in range(n):
            if mask >> i & 1:
                total += angles[i]
            else:
                total -= angles[i]
        if total % 360 == 0:
            return True
    return False

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    angles = list(map(int, data[1:1+n]))
    result = can_return_to_zero(n, angles)
    print("YES" if result else "NO")

if __name__ == "__main__":
    main()
