import math

def manhattan(x1, y1, x2, y2):
    return abs(x1 - x2) + abs(y1 - y2)

def euclidean(x1, y1, x2, y2):
    return math.hypot(x1 - x2, y1 - y2)

def point_on_line(a, b, c, x, y):
    # returns coordinates of point on line ax+by+c=0, given x or y fixed
    pass

def main():
    a, b, c = map(int, input().split())
    x1, y1, x2, y2 = map(int, input().split())

    # Direct Manhattan distance without using avenue
    direct = manhattan(x1, y1, x2, y2)

    # If line is degenerate, just print direct
    # But here line always exists.

    # Candidates for A: intersection with x = x1 and y = y1
    candidates_A = []
    if b != 0:
        # x = x1
        y = (-c - a*x1) / b
        candidates_A.append((x1, y))
    if a != 0:
        # y = y1
        x = (-c - b*y1) / a
        candidates_A.append((x, y1))

    # Candidates for B
    candidates_B = []
    if b != 0:
        y = (-c - a*x2) / b
        candidates_B.append((x2, y))
    if a != 0:
        x = (-c - b*y2) / a
        candidates_B.append((x, y2))

    # Also add intersection points of line with vertical/horizontal lines through integer coordinates near A/B
    # But maybe not needed.

    # Try all pairs of candidates_A and candidates_B
    best = direct
    for P in candidates_A:
        for Q in candidates_B:
            dist = manhattan(x1, y1, P[0], P[1]) + euclidean(P[0], P[1], Q[0], Q[1]) + manhattan(Q[0], Q[1], x2, y2)
            if dist < best:
                best = dist

    # Also try case where P = Q (go to same point on avenue)
    for P in candidates_A:
        # Q = P
        dist = manhattan(x1, y1, P[0], P[1]) + manhattan(P[0], P[1], x2, y2)
        if dist < best:
            best = dist
    for Q in candidates_B:
        # P = Q
        dist = manhattan(x1, y1, Q[0], Q[1]) + manhattan(Q[0], Q[1], x2, y2)
        if dist < best:
            best = dist

    # Also, the minimal Manhattan point on line for A might not be exactly at x=x1 or y=y1, 
    # but somewhere in between. To be safe, let's also sample some points along line near A and B.
    # Parameter t along the line: direction vector (b, -a) or (-b, a)
    if a != 0 or b != 0:
        # Choose a parameterization: if b!=0, use x as parameter, else use y
        if abs(b) > 1e-9:
            # x as parameter
            def y_from_x(x):
                return (-c - a*x) / b
            # Sample around A's x
            xs = [x1 - 2, x1 - 1, x1, x1 + 1, x1 + 2]
            for x in xs:
                y = y_from_x(x)
                candidates_A.append((x, y))
            # Sample around B's x
            xs = [x2 - 2, x2 - 1, x2, x2 + 1, x2 + 2]
            for x in xs:
                y = y_from_x(x)
                candidates_B.append((x, y))
        else:
            # vertical line x = -c/a
            x_val = -c / a
            # sample y around A and B
            ys = [y1 - 2, y1 - 1, y1, y1 + 1, y1 + 2]
            for y in ys:
                candidates_A.append((x_val, y))
            ys = [y2 - 2, y2 - 1, y2, y2 + 1, y2 + 2]
            for y in ys:
                candidates_B.append((x_val, y))

    # Remove duplicates for efficiency
    candidates_A = list(set(candidates_A))
    candidates_B = list(set(candidates_B))

    # Try all pairs again with extended candidates
    for P in candidates_A:
        for Q in candidates_B:
            dist = manhattan(x1, y1, P[0], P[1]) + euclidean(P[0], P[1], Q[0], Q[1]) + manhattan(Q[0], Q[1], x2, y2)
            if dist < best:
                best = dist

    print("{:.10f}".format(best))

if __name__ == "__main__":
    main()

