from sys import stdin
from collections import deque

def solve():
    s = stdin.readline().strip()
    n = len(s)
    digits = [int(ch) for ch in s]

    ans = [[0]*10 for _ in range(10)]

    # Precompute for each (x,y) the dist matrix
    for x in range(10):
        for y in range(10):
            # Build graph
            adj = [[] for _ in range(10)]
            for d in range(10):
                adj[d].append((d + x) % 10)
                adj[d].append((d + y) % 10)

            # BFS from each start
            dist = [[-1]*10 for _ in range(10)]
            for start in range(10):
                dist[start][start] = 0
                q = deque([start])
                while q:
                    u = q.popleft()
                    for v in adj[u]:
                        if dist[start][v] == -1:
                            dist[start][v] = dist[start][u] + 1
                            q.append(v)

            # Check pairs in s
            total = 0
            possible = True
            for i in range(n-1):
                a, b = digits[i], digits[i+1]
                if dist[a][b] == -1:
                    possible = False
                    break
                total += dist[a][b] - 1
            if possible:
                ans[x][y] = total
            else:
                ans[x][y] = -1

    # Output
    out_lines = []
    for i in range(10):
        out_lines.append(' '.join(map(str, ans[i])))
    print('\n'.join(out_lines))

if __name__ == "__main__":
    solve()

