            for price in a:
                if price <= T:
                    T -= price
                    total_candies += 1
            continue
        total_candies += full_rounds * round_count
        T -= full_rounds * round_sum
        # after buying full rounds, buy whatever possible in order
        for price in a:
            if price <= T:
                T -= price
                total_candies += 1

    print(total_candies)

