def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    n, m = int(input_data[0]), int(input_data[1])
    a = list(map(int, input_data[2:2 + n]))

    # If n > m, by pigeonhole principle two numbers are congruent modulo m,
    # so their difference is divisible by m, making the whole product 0 mod m.
    if n > m:
        print(0)
