MOD = 10**9 + 7

def solve():
    import sys
    input = sys.stdin.read
    n, k = map(int, input().split())

    # Precompute factorials and inverse factorials up to n
    fact = [1] * (2*n + 5)
    inv_fact = [1] * (2*n + 5)

    for i in range(2, len(fact)):
        fact[i] = fact[i-1] * i % MOD

    def mod_pow(a, b):
        res = 1
        while b:
            if b & 1:
                res = res * a % MOD
            a = a * a % MOD
            b >>= 1
        return res

    inv_fact[-1] = mod_pow(fact[-1], MOD-2)
    for i in range(len(fact)-2, -1, -1):
        inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

    def C(N, R):
        if R < 0 or R > N:
            return 0
        return fact[N] * inv_fact[R] % MOD * inv_fact[N-R] % MOD

    ans = 0
    # m = number of zeros = total excess
    for m in range(0, min(n, k) + 1):
        if (k - m) % 2 != 0:
            continue
        if m == 0:
            # all ones
            ans = (ans + 1) % MOD
            continue
        # sum over r = 1..m
        s = 0
        for r in range(1, m + 1):
            s = (s + C(n, m) * C(n - m, r) % MOD * C(m - 1, r - 1)) % MOD
        ans = (ans + s) % MOD
    print(ans % MOD)

if __name__ == "__main__":
    solve()

