import sys
from itertools import permutations

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    idx = 2
    constraints = []
    for _ in range(k):
        x = int(data[idx]) - 1      # make 0-based
        sign = data[idx + 1]
        y = int(data[idx + 2]) - 1  # make 0-based
        idx += 3
        constraints.append((x, sign, y))

    # heights list: two 1's, two 2's, ..., two n's
    heights = []
    for i in range(1, n + 1):
        heights.append(i)
        heights.append(i)
    # generate all permutations of heights
    perms = set()
    for perm in permutations(heights):
        perms.add(perm)

    def valid_mausoleum(arr):
        # find first peak: non-decreasing then non-increasing
        i = 0
        # non-decreasing part
        while i + 1 < 2 * n and arr[i] <= arr[i + 1]:
            i += 1
        # non-increasing part
        while i + 1 < 2 * n and arr[i] >= arr[i + 1]:
            i += 1
        return i == 2 * n - 1

    def satisfies_constraints(arr):
        for x, sign, y in constraints:
            a = arr[x]
            b = arr[y]
            if sign == '=':
                if a != b:
                    return False
            elif sign == '<':
                if not (a < b):
                    return False
            elif sign == '>':
                if not (a > b):
                    return False
            elif sign == '<=':
                if not (a <= b):
                    return False
            elif sign == '>=':
                if not (a >= b):
                    return False
        return True

    count = 0
    for perm in perms:
        if valid_mausoleum(perm) and satisfies_constraints(perm):
            count += 1
    print(count)

if __name__ == "__main__":
    solve()
